window.QB_TKP_B23 = [
{"id":"TKP-4301", "q":"Dosen tamu dalam kuliah umum di kampus Anda menyisipkan materi bahwa demokrasi itu sesat dan harus diganti sistem khilafah. Sebagai mahasiswa, sikap Anda?", "opts":[{"t":"Melaporkan dosen tamu tersebut ke pihak rektorat dan menolak materi yang bertentangan dengan Pancasila","s":5},{"t":"Menegur langsung dan mengingatkan forum bahwa kampus bukan tempat menyebar paham khilafah","s":4},{"t":"Diam saja dan tidak mengikuti ajakannya, lalu pergi dari ruangan","s":3},{"t":"Mendengarkan sampai selesai karena menganggap itu hanya pendapat pribadi dosen","s":2},{"t":"Mendukung materinya dan membantu menyebarkan ke grup mahasiswa lain","s":1}], "ex":"Kampus wajib bebas dari doktrin khilafah; mahasiswa harus menolak dan melaporkannya ke rektorat agar ditindaklanjuti."},
{"id":"TKP-4302", "q":"Ketua unit kegiatan mahasiswa mengajak Anda berbaiat ke kelompok yang mengajarkan perjuangan bersenjata sebagai jalan jihad dan membenarkan aksi teror. Tindakan Anda?", "opts":[{"t":"Menolak tegas dan melaporkan kelompok tersebut ke pihak kampus serta aparat keamanan","s":5},{"t":"Menasihati ketua UKM agar menghentikan perekrutan berkedok baiat tersebut","s":4},{"t":"Menolak ajakannya tetapi tidak melapor karena takut dianggap pengkhianat","s":3},{"t":"Minta waktu berpikir sambil tetap hadir di pertemuan mereka","s":2},{"t":"Menerima baiat karena tertarik dengan iming-iming persaudaraan mereka","s":1}], "ex":"Baiat ke kelompok yang membenarkan teror adalah pintu masuk jaringan ekstrem; tolak dan laporkan ke kampus serta aparat."},
{"id":"TKP-4303", "q":"Teman sekamar kos menyebarkan pamflet perekrutan organisasi ekstrem yang dibubarkan pemerintah di asrama mahasiswa. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengelola asrama dan pihak berwajib disertai bukti pamfletnya","s":5},{"t":"Memperingatkan teman sekamar agar berhenti menyebarkan pamflet terlarang itu","s":4},{"t":"Membuang pamfletnya diam-diam tanpa menegur atau melapor","s":3},{"t":"Membiarkannya karena menganggap itu urusan pribadi teman sekamar","s":2},{"t":"Ikut membantu menyebarkan pamflet ke kamar-kamar lain","s":1}], "ex":"Menyebarkan materi organisasi ekstrem yang dibubarkan pemerintah adalah pelanggaran hukum; laporkan dengan bukti."},
{"id":"TKP-4304", "q":"Di grup chat angkatan, beberapa mahasiswa rutin melontarkan ujaran intoleran yang menghina mahasiswa berbeda keyakinan. Sebagai anggota grup, Anda?", "opts":[{"t":"Melaporkan pelaku ke pihak kampus dan meminta admin menertibkan grup","s":5},{"t":"Menegur di grup agar berhenti menyebar ujaran intoleran","s":4},{"t":"Keluar dari grup tanpa menegur atau melapor","s":3},{"t":"Tetap di grup dan menganggapnya sekadar candaan anak muda","s":2},{"t":"Ikut menimpali ujaran intoleran tersebut agar diterima pergaulan","s":1}], "ex":"Ujaran intoleran merusak kerukunan kampus; tegur dan laporkan agar pelakunya dibina, jangan dinormalisasi sebagai candaan."},
{"id":"TKP-4305", "q":"Senior saat ospek memaksa mahasiswa baru menghafal doktrin khilafah bahwa Pancasila harus diganti dan yang menolak dianggap musuh. Anda salah satu peserta ospek. Sikap Anda?", "opts":[{"t":"Menolak doktrin tersebut dan melaporkannya ke panitia ospek serta pihak kampus","s":5},{"t":"Menolak menghafal dan mengajak peserta lain untuk tidak ikut","s":4},{"t":"Berpura-pura menghafal agar lolos ospek, lalu melupakannya","s":3},{"t":"Menghafal saja karena takut tidak diluluskan dari ospek","s":2},{"t":"Menghafal sungguh-sungguh dan meyakininya sebagai kebenaran","s":1}], "ex":"Ospek tidak boleh menjadi ajang indoktrinasi anti-Pancasila; tolak dan laporkan agar pelakunya ditindak kampus."},
{"id":"TKP-4306", "q":"Anda ditawari beasiswa penuh dari sebuah yayasan, tetapi belakangan tahu yayasan itu menyalurkan dana ke jaringan radikal. Sikap Anda?", "opts":[{"t":"Menolak beasiswa itu dan melaporkan yayasan tersebut ke pihak berwenang","s":5},{"t":"Menolak beasiswa dan memperingatkan teman lain agar tidak menerimanya","s":4},{"t":"Menolak beasiswa secara diam-diam tanpa memberitahu siapa pun","s":3},{"t":"Tetap menerima beasiswa karena butuh biaya kuliah, asal tidak ikut kegiatannya","s":2},{"t":"Menerima beasiswa dan aktif di kegiatan yayasan tersebut","s":1}], "ex":"Dana dari jaringan radikal mengikat penerima pada kepentingannya; tolak dan laporkan agar tidak ada korban berikutnya."},
{"id":"TKP-4307", "q":"Dosen pembimbing skripsi meminta Anda menyisipkan narasi tegaknya khilafah dalam bab pembahasan, jika tidak skripsi tidak akan disetujui. Tindakan Anda?", "opts":[{"t":"Menolak dan melaporkan pemerasan akademik itu ke pihak fakultas","s":5},{"t":"Menolak menyisipkan narasi khilafah dan meminta pembimbing pengganti","s":4},{"t":"Menunda bimbingan sambil mencari cara agar tidak perlu menyisipkannya","s":3},{"t":"Menyisipkan sedikit saja agar skripsi cepat disetujui","s":2},{"t":"Menyisipkan narasi khilafah sesuai permintaan demi kelulusan","s":1}], "ex":"Menukar kelulusan dengan penyebaran paham khilafah adalah pelanggaran akademik dan hukum; laporkan ke fakultas."},
{"id":"TKP-4308", "q":"Kajian rutin di masjid kampus perlahan berubah menjadi forum indoktrinasi yang mengajarkan kebencian intoleran terhadap kelompok lain. Anda jamaah rutin kajian itu. Sikap Anda?", "opts":[{"t":"Berhenti ikut dan melaporkan materi intolerannya ke takmir serta pihak kampus","s":5},{"t":"Menegur pemateri agar kembali ke kajian yang menyejukkan","s":4},{"t":"Berhenti datang tanpa menjelaskan alasan kepada siapa pun","s":3},{"t":"Tetap datang karena segan dengan teman-teman kajian","s":2},{"t":"Makin aktif karena merasa materinya membuka wawasan perjuangan","s":1}], "ex":"Kajian yang mengajarkan kebencian intoleran harus ditinggalkan dan dilaporkan agar tidak meracuni jamaah lain."},
{"id":"TKP-4309", "q":"Teman sekelas mengajak Anda nonton bareng video propaganda kelompok teror di kosnya dan melarang merekam atau bercerita ke siapa pun. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ajakan menonton propaganda teror ke pihak berwajib","s":5},{"t":"Menolak ajakannya dan memperingatkannya bahwa itu konten terlarang","s":4},{"t":"Menolak dengan alasan sibuk, tanpa melapor","s":3},{"t":"Ikut menonton sekali karena penasaran, lalu tidak ikut lagi","s":2},{"t":"Ikut menonton dan merahasiakannya sesuai permintaan teman","s":1}], "ex":"Propaganda teror dirancang untuk merekrut penontonnya; jangan tonton, tolak, dan laporkan agar penyebarnya ditindak."},
{"id":"TKP-4310", "q":"Dinding toilet dan lorong kampus dipenuhi grafiti simbol kelompok ekstrem dan tulisan provokatif anti-pemerintah. Anda melihatnya setiap hari. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pihak kampus agar grafiti dihapus dan pelakunya dilacak","s":5},{"t":"Mengajak teman-teman menghapus grafiti simbol ekstrem tersebut bersama","s":4},{"t":"Mengabaikannya karena menganggap itu ulah iseng mahasiswa","s":3},{"t":"Memotretnya untuk bahan candaan di media sosial","s":2},{"t":"Menambahkan grafiti dukungan karena merasa pesannya benar","s":1}], "ex":"Simbol kelompok ekstrem di ruang publik adalah propaganda visual; laporkan agar dibersihkan dan pelakunya dibina."},
{"id":"TKP-4311", "q":"Dalam diskusi kelas, seorang teman menyatakan serangan teror terhadap aparat adalah hal yang dibenarkan sebagai bentuk perlawanan. Sikap Anda sebagai teman sekelas?", "opts":[{"t":"Menolak pernyataan itu dan melaporkannya ke dosen serta pihak kampus","s":5},{"t":"Mendebatnya di forum diskusi bahwa teror tidak bisa dibenarkan alasan apa pun","s":4},{"t":"Diam saja agar diskusi tidak memanas","s":3},{"t":"Menganggapnya sekadar pendapat yang sah dalam diskusi bebas","s":2},{"t":"Menyetujui pernyataannya karena merasa aparat memang zalim","s":1}], "ex":"Pembenaran terhadap aksi teror adalah bibit radikalisasi; bantah secara terbuka dan laporkan ke pihak kampus."},
{"id":"TKP-4312", "q":"Organisasi ekstra kampus menawarkan Anda posisi pengurus dengan iming-iming uang saku dan jaringan, tetapi mensyaratkan loyalitas pada ideologi khilafah mereka. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan modus perekrutan berkedok organisasi itu ke pihak kampus","s":5},{"t":"Menolak tawarannya dan memperingatkan teman lain agar waspada","s":4},{"t":"Menolak secara halus tanpa menjelaskan alasan sebenarnya","s":3},{"t":"Mempertimbangkan karena iming-iming uang sakunya menarik","s":2},{"t":"Menerima posisi itu demi uang saku dan jaringan","s":1}], "ex":"Perekrutan beriming-iming materi dengan syarat ideologi khilafah adalah modus jaringan radikal; tolak dan laporkan."},
{"id":"TKP-4313", "q":"Anda menemukan tumpukan buku ajaran radikal yang mengajarkan kebencian intoleran terselip di rak perpustakaan kampus. Tindakan Anda?", "opts":[{"t":"Melaporkan temuan itu ke pustakawan dan pihak kampus agar buku disita","s":5},{"t":"Memberitahu pustakawan agar buku-buku itu disingkirkan dari rak","s":4},{"t":"Mengembalikan buku ke rak lain tanpa melapor","s":3},{"t":"Membiarkannya karena menganggap semua buku boleh dibaca","s":2},{"t":"Membawa pulang beberapa untuk dibaca dan disebarkan ke teman","s":1}], "ex":"Buku ajaran radikal yang disusupkan ke perpustakaan adalah upaya indoktrinasi; laporkan agar disita pihak kampus."},
{"id":"TKP-4314", "q":"Aksi demonstrasi mahasiswa ditunggangi orator luar yang menghasut massa melakukan kekerasan dan meneriakkan yel-yel intoleran. Anda peserta aksi. Sikap Anda?", "opts":[{"t":"Meninggalkan barisan dan melaporkan provokator itu ke aparat keamanan","s":5},{"t":"Menjauh dari orator dan mengajak peserta lain tidak terprovokasi","s":4},{"t":"Tetap di lokasi tetapi tidak ikut meneriakkan yel-yelnya","s":3},{"t":"Ikut meneriakkan yel-yel karena terbawa suasana massa","s":2},{"t":"Maju ke depan dan ikut menghasut massa agar makin berani","s":1}], "ex":"Demonstrasi yang ditunggangi hasutan kekerasan dan intoleransi harus ditinggalkan; laporkan provokatornya ke aparat."},
{"id":"TKP-4315", "q":"Anda tidak sengaja melihat teman sekamar menyimpan buku panduan merakit bahan peledak dan peta lokasi keramaian. Ia mengaku hanya koleksi bacaan ekstrem. Tindakan Anda?", "opts":[{"t":"Segera melaporkan temuan itu ke pihak kepolisian","s":5},{"t":"Mendesak teman sekamar memusnahkan barang itu dan melapor ke kampus","s":4},{"t":"Memintanya menyembunyikan lebih rapi agar tidak ketahuan orang","s":3},{"t":"Mengabaikannya karena percaya itu hanya koleksi bacaan","s":2},{"t":"Merahasiakannya demi menjaga persahabatan sekamar","s":1}], "ex":"Panduan bahan peledak plus peta keramaian adalah indikasi rencana teror; wajib segera dilaporkan ke kepolisian."},
{"id":"TKP-4316", "q":"Seorang dosen yang Anda kagumi ternyata diketahui menjadi ideolog kelompok pengusung khilafah di luar kampus. Sikap Anda sebagai mahasiswanya?", "opts":[{"t":"Tetap profesional di kelas, tetapi melaporkan informasi itu ke pihak kampus dan berwajib","s":5},{"t":"Menjaga jarak dan tidak lagi mengikuti kajian-kajian di luar kelas yang ia adakan","s":4},{"t":"Tetap mengaguminya sebagai dosen tanpa memedulikan aktivitas di luar kampus","s":3},{"t":"Mencari tahu lebih jauh tentang kelompoknya karena penasaran","s":2},{"t":"Bergabung dengan kelompoknya karena percaya pada sang dosen","s":1}], "ex":"Kekaguman pada dosen tidak boleh membutakan; ideolog khilafah harus dilaporkan agar kampus mengambil tindakan."},
{"id":"TKP-4317", "q":"Dalam lomba debat kampus, lawan debat Anda menyisipkan doktrin intoleran dan ajakan menegakkan khilafah di setiap argumennya. Sikap Anda sebagai peserta?", "opts":[{"t":"Membantah argumennya secara akademis dan melaporkan muatan doktrinnya ke dewan juri","s":5},{"t":"Membantah dengan data bahwa khilafah bertentangan dengan konstitusi Indonesia","s":4},{"t":"Fokus pada teknik debat tanpa menanggapi muatan doktrinnya","s":3},{"t":"Mengalah dalam debat agar tidak berkonflik dengannya","s":2},{"t":"Sepakat dengannya karena argumennya terdengar meyakinkan","s":1}], "ex":"Forum debat bukan panggung doktrin khilafah; bantah secara akademis dan laporkan ke dewan juri."},
{"id":"TKP-4318", "q":"Grup belajar Anda diajak memboikot upacara bendera kampus dengan alasan menghormati bendera adalah perbuatan syirik menurut paham ekstrem mereka. Sikap Anda?", "opts":[{"t":"Menolak ajakan boikot dan melaporkan penyebar paham itu ke pihak kampus","s":5},{"t":"Tetap ikut upacara dan mengajak teman lain tidak terpengaruh ajakan boikot","s":4},{"t":"Tidak ikut upacara tetapi juga tidak ikut menyebarkan ajakannya","s":3},{"t":"Ikut boikot agar tidak dikucilkan dari grup belajar","s":2},{"t":"Ikut memboikot dan membantu menyebarkan alasannya","s":1}], "ex":"Upacara bendera adalah wujud cinta tanah air; ajakan memboikotnya atas nama paham ekstrem harus ditolak dan dilaporkan."},
{"id":"TKP-4319", "q":"Senior menawarkan pelatihan bela diri gratis di luar kampus, tetapi ternyata materinya adalah kaderisasi militan kelompok ekstrem. Anda sudah dua kali ikut. Sikap Anda?", "opts":[{"t":"Berhenti ikut dan melaporkan kegiatan kaderisasi itu ke pihak berwajib","s":5},{"t":"Berhenti ikut dan memperingatkan teman lain yang diajak senior tersebut","s":4},{"t":"Berhenti ikut secara diam-diam tanpa melapor","s":3},{"t":"Tetap ikut karena latihannya memang bermanfaat untuk bela diri","s":2},{"t":"Terus ikut dan naik ke level kaderisasi berikutnya","s":1}], "ex":"Pelatihan berkedok bela diri yang berisi kaderisasi militan harus ditinggalkan dan dilaporkan ke pihak berwajib."},
{"id":"TKP-4320", "q":"Kantin kampus menjadi tempat berkumpul rutin kelompok diskusi yang menyebarkan kebencian intoleran terhadap pemerintah dan kelompok lain. Anda sering makan di sana. Sikap Anda?", "opts":[{"t":"Melaporkan aktivitas kelompok itu ke pihak kampus agar ditertibkan","s":5},{"t":"Menegur mereka agar tidak menyebar kebencian di ruang publik kampus","s":4},{"t":"Pindah tempat makan tanpa menegur atau melapor","s":3},{"t":"Tetap makan di sana sambil sesekali mendengarkan diskusinya","s":2},{"t":"Ikut bergabung karena diskusinya terasa seru","s":1}], "ex":"Ruang publik kampus tidak boleh dikuasai penyebar kebencian intoleran; laporkan agar ditertibkan pihak kampus."},
{"id":"TKP-4321", "q":"Saat gladi wisuda, panitia luar membagikan petisi tegaknya khilafah dan meminta tanda tangan para wisudawan. Sikap Anda?", "opts":[{"t":"Menolak menandatangani dan melaporkan pembagian petisi itu ke pihak kampus","s":5},{"t":"Menolak dan mengajak wisudawan lain untuk tidak menandatangani","s":4},{"t":"Menolak dengan halus tanpa melapor","s":3},{"t":"Menandatangani karena sungkan dengan panitia","s":2},{"t":"Menandatangani dan membantu mengedarkan petisi ke wisudawan lain","s":1}], "ex":"Momen wisuda tidak boleh dimanfaatkan untuk penggalangan dukungan khilafah; tolak dan laporkan ke pihak kampus."},
{"id":"TKP-4322", "q":"Teman Anda yang magang di sebuah instansi pemerintah justru menyebarkan paham radikal kepada para pegawai di sana. Anda mengetahuinya. Tindakan Anda?", "opts":[{"t":"Melaporkan perbuatannya ke pihak instansi tempat ia magang","s":5},{"t":"Menasihatinya agar berhenti menyebar paham radikal di tempat magang","s":4},{"t":"Menasihati secara pribadi tanpa melapor ke instansi","s":3},{"t":"Membiarkannya karena itu di luar urusan Anda","s":2},{"t":"Mendukungnya karena merasa instansi itu memang perlu dicerahkan","s":1}], "ex":"Penyebaran paham radikal di instansi pemerintah membahayakan birokrasi; laporkan ke pihak instansi agar ditindak."},
{"id":"TKP-4323", "q":"Kegiatan bakti sosial kampus ternyata dipakai panitia sebagai kedok penggalangan dana untuk jaringan kelompok ekstrem. Anda peserta baksos. Sikap Anda?", "opts":[{"t":"Mundur dari kegiatan dan melaporkan penggalangan dana itu ke pihak berwajib","s":5},{"t":"Mundur dan memperingatkan peserta lain agar tidak menyumbang","s":4},{"t":"Tidak menyumbang tetapi tetap ikut kegiatan sampai selesai","s":3},{"t":"Menyumbang sedikit karena kasihan dengan panitia","s":2},{"t":"Menyumbang besar dan mengajak teman ikut menyumbang","s":1}], "ex":"Bakti sosial berkedok penggalangan dana jaringan ekstrem harus ditinggalkan dan dilaporkan ke pihak berwajib."},
{"id":"TKP-4324", "q":"Seorang dosen diketahui memberi nilai berdasarkan afiliasi kelompoknya yang intoleran: mahasiswa di luar kelompoknya selalu dapat nilai rendah. Sikap Anda?", "opts":[{"t":"Melaporkan praktik diskriminatif itu ke pihak fakultas disertai bukti","s":5},{"t":"Mengumpulkan bukti bersama teman senasib lalu melapor kolektif","s":4},{"t":"Menerima saja dan berusaha masuk ke kelompoknya demi nilai","s":3},{"t":"Diam karena takut nilai makin jatuh jika melapor","s":2},{"t":"Ikut bergabung ke kelompok intolerannya demi nilai bagus","s":1}], "ex":"Diskriminasi nilai berbasis afiliasi kelompok intoleran merusak integritas akademik; laporkan ke fakultas dengan bukti."},
{"id":"TKP-4325", "q":"Seminar kebangsaan di kampus Anda disabotase sekelompok orang yang meneriakkan penolakan intoleran terhadap pembicara berbeda keyakinan. Anda peserta seminar. Sikap Anda?", "opts":[{"t":"Tetap di forum, mendukung pembicara, dan melaporkan pelaku sabotase ke panitia serta keamanan","s":5},{"t":"Menyuarakan keberatan terhadap aksi intoleran itu di forum","s":4},{"t":"Keluar ruangan agar tidak terlibat keributan","s":3},{"t":"Diam saja karena takut menjadi sasaran amukan mereka","s":2},{"t":"Ikut meneriakkan penolakan karena sependapat dengan mereka","s":1}], "ex":"Sabotase forum kebangsaan atas nama intoleransi harus dilawan; dukung pembicara dan laporkan pelakunya."},
{"id":"TKP-4326", "q":"Rekan kerja Anda rajin membagikan konten ceramah ekstrem yang menghasut kebencian intoleran di status media sosialnya dan dilihat banyak kolega. Sikap Anda?", "opts":[{"t":"Melaporkan akun dan kontennya ke atasan serta ke pihak berwenang","s":5},{"t":"Menasihatinya secara pribadi agar berhenti menyebar konten ekstrem","s":4},{"t":"Meng-unfollow akunnya tanpa menegur atau melapor","s":3},{"t":"Membiarkannya karena menganggap media sosial adalah ranah pribadi","s":2},{"t":"Ikut membagikan kontennya karena merasa isinya benar","s":1}], "ex":"ASN penyebar konten ekstrem di media sosial merusak citra birokrasi; nasihati, dan laporkan bila tidak berhenti."},
{"id":"TKP-4327", "q":"Anda menemukan grup media sosial tertutup berisi ASN satu instansi yang mendiskusikan rencana mengganti ideologi negara dengan khilafah. Tindakan Anda?", "opts":[{"t":"Melaporkan grup tersebut ke pimpinan instansi dan aparat keamanan","s":5},{"t":"Keluar dari grup dan memperingatkan anggotanya tentang bahayanya","s":4},{"t":"Keluar diam-diam tanpa melapor karena takut dicap pengkhianat","s":3},{"t":"Tetap di grup hanya sebagai penyimak pasif","s":2},{"t":"Aktif berdiskusi karena tertarik dengan gagasannya","s":1}], "ex":"Grup ASN yang merencanakan penggantian ideologi negara adalah ancaman serius; laporkan ke pimpinan dan aparat."},
{"id":"TKP-4328", "q":"Seorang ASN viral karena videonya berorasi intoleran menolak rumah ibadah agama lain di lingkungannya. Ia rekan satu kantor Anda. Sikap Anda?", "opts":[{"t":"Melaporkan perbuatannya ke atasan dan mendukung proses pembinaan disiplin","s":5},{"t":"Menasihatinya bahwa tindakannya mencoreng nama ASN dan institusi","s":4},{"t":"Tidak ikut campur karena itu terjadi di luar jam kerja","s":3},{"t":"Membelanya dengan alasan ia hanya menyampaikan aspirasi warga","s":2},{"t":"Ikut menyebarkan videonya sebagai bentuk dukungan","s":1}], "ex":"ASN yang viral menyebar intoleransi wajib dibina dan dilaporkan; pembelaan atas nama aspirasi tidak dapat dibenarkan."},
{"id":"TKP-4329", "q":"Atasan Anda mengunggah ujaran kebencian bernada ekstrem terhadap kelompok tertentu dan meminta bawahan me-like dan membagikannya. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan unggahan atasan ke inspektorat atau pimpinan lebih tinggi","s":5},{"t":"Tidak me-like maupun membagikan, lalu menasihati atasan secara santun","s":4},{"t":"Mengabaikan perintahnya tanpa melapor","s":3},{"t":"Me-like saja agar tidak dimusuhi atasan, tanpa membagikan","s":2},{"t":"Me-like dan membagikan demi menjaga hubungan baik dengan atasan","s":1}], "ex":"Perintah atasan menyebar ujaran ekstrem tidak wajib ditaati; tolak dan laporkan ke inspektorat atau pimpinan di atasnya."},
{"id":"TKP-4330", "q":"Akun anonim menyebarkan fitnah bahwa instansi Anda melindungi jaringan teror. Postingan itu viral dan meresahkan pegawai. Sebagai humas instansi, Anda?", "opts":[{"t":"Menyusun klarifikasi resmi, melapor ke polisi, dan mengedukasi pegawai agar tidak terprovokasi","s":5},{"t":"Membuat bantahan resmi di kanal media sosial instansi","s":4},{"t":"Menunggu arahan pimpinan tanpa mengambil inisiatif","s":3},{"t":"Ikut berkomentar membela instansi dengan emosi di kolom komentar","s":2},{"t":"Mempercayai fitnah itu dan menyebarkannya ke grup pegawai","s":1}], "ex":"Fitnah soal jaringan teror harus dijawab dengan klarifikasi resmi dan laporan polisi, bukan emosi di kolom komentar."},
{"id":"TKP-4331", "q":"Teman Anda sesama CPNS ketahuan menjadi admin kanal yang menyebarkan doktrin khilafah dan ajakan intoleran. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pihak berwenang dan ke instansinya sebagai pelanggaran berat","s":5},{"t":"Mendesaknya berhenti dan menghapus kanal tersebut","s":4},{"t":"Menjauhinya tanpa melapor","s":3},{"t":"Tetap berteman seperti biasa karena itu urusan pribadinya","s":2},{"t":"Ikut menjadi admin karena diajak dan dijanjikan penghasilan","s":1}], "ex":"CPNS admin kanal doktrin khilafah melanggar sumpah ASN; laporkan ke instansi dan pihak berwenang."},
{"id":"TKP-4332", "q":"Di kolom komentar akun resmi instansi, seseorang rutin menulis hasutan ekstrem mengajak menggulingkan pemerintah yang sah. Sebagai admin akun, Anda?", "opts":[{"t":"Menghapus komentar, memblokir akun, dan melaporkannya ke pihak berwajib","s":5},{"t":"Menyembunyikan komentar hasutan dan memperingatkan pemilik akun","s":4},{"t":"Membiarkan karena menganggap itu kebebasan berpendapat","s":3},{"t":"Membalas komentarnya dengan debat kusir","s":2},{"t":"Menyukai komentarnya karena sependapat","s":1}], "ex":"Hasutan ekstrem di akun resmi instansi harus dihapus, diblokir, dan dilaporkan; bukan ruang debat kusir."},
{"id":"TKP-4333", "q":"Seorang pegawai membuat video parodi intoleran yang menghina simbol agama lain dengan dalih humor, lalu viral dan memicu kemarahan. Ia rekan Anda. Sikap Anda?", "opts":[{"t":"Melaporkan ke atasan agar dibina dan videonya dihapus","s":5},{"t":"Menasihatinya bahwa humor intoleran merusak kerukunan dan citra ASN","s":4},{"t":"Tidak menonton dan tidak ikut menyebarkan","s":3},{"t":"Menontonnya karena penasaran, lalu menghapus riwayat","s":2},{"t":"Ikut menyebarkan karena menganggapnya lucu","s":1}], "ex":"Parodi penghinaan simbol agama adalah ujaran intoleran; ASN pelakunya wajib dibina dan kontennya dihapus."},
{"id":"TKP-4334", "q":"Anda diajak bergabung ke siaran langsung yang membahas cara menyusupkan paham radikal ke birokrasi lewat jalur rekrutmen. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan siaran serta penyelenggaranya ke pihak berwajib","s":5},{"t":"Menolak dan memperingatkan teman yang mengajak","s":4},{"t":"Menolak ajakan tanpa melapor","s":3},{"t":"Menonton sebentar karena penasaran dengan isinya","s":2},{"t":"Bergabung dan mencatat strateginya untuk diterapkan","s":1}], "ex":"Siaran strategi penyusupan paham radikal ke birokrasi adalah ancaman; tolak dan laporkan penyelenggaranya."},
{"id":"TKP-4335", "q":"Foto Anda dicatut akun penyebar propaganda khilafah sebagai testimoni pendukung mereka. Tindakan Anda?", "opts":[{"t":"Melaporkan pencatutan itu ke polisi dan membuat klarifikasi publik","s":5},{"t":"Meminta akun tersebut menghapus foto Anda dan membuat klarifikasi","s":4},{"t":"Mengabaikannya karena merasa tidak merugikan","s":3},{"t":"Membiarkan karena takut berurusan dengan mereka","s":2},{"t":"Membiarkan bahkan merasa bangga dianggap pendukung","s":1}], "ex":"Pencatutan identitas untuk propaganda khilafah merugikan nama baik; laporkan ke polisi dan klarifikasi secara publik."},
{"id":"TKP-4336", "q":"Grup alumni sekolah Anda berubah menjadi corong penyebaran teori konspirasi ekstrem yang menghasut kebencian intoleran. Anda anggota grup. Sikap Anda?", "opts":[{"t":"Melaporkan admin dan konten berbahaya ke platform serta pihak berwajib bila menghasut kekerasan","s":5},{"t":"Memprotes di grup dan meminta kembali ke tujuan awal silaturahmi","s":4},{"t":"Membisukan notifikasi grup tanpa protes","s":3},{"t":"Tetap membaca karena kadang informasinya menarik","s":2},{"t":"Aktif ikut menyebarkan teori konspirasi itu","s":1}], "ex":"Grup alumni yang menjadi corong hasutan ekstrem harus diprotes; laporkan bila sudah menghasut kekerasan."},
{"id":"TKP-4337", "q":"Seorang influencer yang Anda ikuti terang-terangan mengkampanyekan penolakan intoleran terhadap perbedaan dan memuji aksi teror. Sikap Anda sebagai pengikutnya?", "opts":[{"t":"Berhenti mengikuti, melaporkan kontennya, dan mengedukasi pengikut lain tentang bahayanya","s":5},{"t":"Berhenti mengikuti dan melaporkan akunnya ke platform","s":4},{"t":"Berhenti mengikuti secara diam-diam","s":3},{"t":"Tetap mengikuti karena konten lainnya menghibur","s":2},{"t":"Tetap mengikuti dan membela di kolom komentar","s":1}], "ex":"Influencer pemuji teror harus ditinggalkan dan dilaporkan; popularitas tidak membenarkan penyebaran paham ekstrem."},
{"id":"TKP-4338", "q":"Rekan kerja meminta Anda meminjamkan akun media sosial dinas untuk menyebarkan seruan aksi massa bernuansa intoleran. Sikap Anda?", "opts":[{"t":"Menolak tegas dan melaporkan permintaan itu ke atasan","s":5},{"t":"Menolak dan menjelaskan akun dinas tidak boleh dipakai untuk seruan intoleran","s":4},{"t":"Menolak dengan alasan lupa kata sandi","s":3},{"t":"Meminjamkan dengan syarat tidak menyebut nama Anda","s":2},{"t":"Meminjamkan karena tidak enak menolak rekan","s":1}], "ex":"Akun dinas adalah aset negara; meminjamkannya untuk seruan intoleran adalah pelanggaran berat yang harus dilaporkan."},
{"id":"TKP-4339", "q":"Anda melihat unggahan teman yang membagikan tutorial menghindari deteksi aparat saat menyebar paham khilafah. Tindakan Anda?", "opts":[{"t":"Melaporkan unggahan itu ke pihak berwajib sebagai indikasi jaringan","s":5},{"t":"Memperingatkan teman bahwa tindakannya melanggar hukum","s":4},{"t":"Mengabaikan karena tidak ingin ikut campur","s":3},{"t":"Menyimpan tutorialnya untuk jaga-jaga","s":2},{"t":"Ikut membagikan karena merasa informasinya berguna","s":1}], "ex":"Tutorial menghindari aparat dalam penyebaran khilafah adalah bukti aktivitas jaringan; laporkan ke pihak berwajib."},
{"id":"TKP-4340", "q":"Dalam rapat virtual, seorang peserta menyalakan latar bertuliskan slogan kelompok ekstrem dan meneriakkan yel-yel intoleran. Anda peserta rapat. Sikap Anda?", "opts":[{"t":"Melaporkan ke pimpinan rapat dan pihak berwenang setelah acara","s":5},{"t":"Menegur di forum rapat agar menghentikan aksinya","s":4},{"t":"Mematikan kamera dan mengabaikannya","s":3},{"t":"Tertawa karena menganggapnya lucu","s":2},{"t":"Ikut meneriakkan yel-yelnya","s":1}], "ex":"Simbol dan yel-yel kelompok ekstrem di forum resmi tidak bisa ditoleransi; tegur dan laporkan ke pimpinan."},
{"id":"TKP-4341", "q":"Tetangga Anda yang seorang ASN aktif mengunggah ancaman bernada teror kepada warga berbeda keyakinan di grup lingkungan. Sikap Anda sebagai tetangga?", "opts":[{"t":"Melaporkan ke ketua lingkungan, instansinya, dan pihak kepolisian","s":5},{"t":"Menegur langsung agar berhenti menyebar ancaman","s":4},{"t":"Menghindari berinteraksi dengannya","s":3},{"t":"Membiarkan karena takut bermusuhan dengan tetangga","s":2},{"t":"Mendukungnya karena sependapat","s":1}], "ex":"Ancaman bernada teror oleh ASN di lingkungan warga harus dilaporkan ke ketua lingkungan, instansi, dan polisi."},
{"id":"TKP-4342", "q":"Akun media sosial Anda diretas dan dipakai menyebarkan propaganda kelompok radikal. Tindakan pertama Anda?", "opts":[{"t":"Mengamankan akun, melaporkan peretasan ke platform dan polisi, serta membuat klarifikasi","s":5},{"t":"Mengamankan akun kembali dan menghapus semua postingan propaganda","s":4},{"t":"Membuat akun baru dan meninggalkan akun lama","s":3},{"t":"Membiarkan karena tidak tahu cara mengatasinya","s":2},{"t":"Membiarkan karena isi propagandanya sejalan dengan pandangan Anda","s":1}], "ex":"Akun diretas untuk propaganda radikal harus segera diamankan, dilaporkan ke platform dan polisi, plus klarifikasi publik."},
{"id":"TKP-4343", "q":"Seorang calon legislatif menjanjikan dana kampanye dari donatur yang terafiliasi jaringan ekstrem dengan syarat menyuarakan agenda khilafah. Anda tim suksesnya. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tawaran itu ke Bawaslu serta pihak berwajib","s":5},{"t":"Mundur dari tim sukses dan memperingatkan kandidat tentang bahayanya","s":4},{"t":"Mundur diam-diam tanpa melapor","s":3},{"t":"Tetap di tim tetapi menolak mengurusi dana tersebut","s":2},{"t":"Menerima dan membantu menyalurkan dana itu","s":1}], "ex":"Dana kampanye dari jaringan ekstrem dengan agenda khilafah adalah pelanggaran pemilu dan hukum; laporkan ke Bawaslu."},
{"id":"TKP-4344", "q":"Di forum daring ASN se-Indonesia, seseorang menyebarkan daftar nama pegawai yang dituduh antek kelompok intoleran untuk diintimidasi. Anda anggota forum. Sikap Anda?", "opts":[{"t":"Melaporkan penyebar daftar itu ke admin forum dan pihak berwajib","s":5},{"t":"Memprotes di forum agar daftar fitnah itu dihapus","s":4},{"t":"Keluar dari forum tanpa protes","s":3},{"t":"Menyimpan daftarnya untuk kewaspadaan pribadi","s":2},{"t":"Ikut menyebarkan daftar itu ke grup lain","s":1}], "ex":"Daftar fitnah untuk mengintimidasi adalah persekusi digital; laporkan penyebarnya ke admin dan pihak berwajib."},
{"id":"TKP-4345", "q":"Anak Anda menunjukkan video pendek yang memuliakan pelaku teror sebagai pahlawan dan mengajak penonton bergabung. Sikap Anda sebagai orang tua?", "opts":[{"t":"Melaporkan video itu, memblokir sumbernya, dan menjelaskan bahaya paham teror ke anak","s":5},{"t":"Memblokir sumber video dan menasihati anak agar tidak terpengaruh","s":4},{"t":"Melarang anak menonton tanpa penjelasan","s":3},{"t":"Membiarkan karena menganggap anak hanya iseng menonton","s":2},{"t":"Ikut menonton dan membenarkan isi video di depan anak","s":1}], "ex":"Konten pemuliaan pelaku teror menarget anak muda; laporkan, blokir sumbernya, dan edukasi anak tentang bahayanya."},
{"id":"TKP-4346", "q":"Rekan sekantor membuat stiker digital bergambar simbol kelompok ekstrem dan menyebarkannya di grup kerja. Sikap Anda?", "opts":[{"t":"Melaporkan ke atasan agar stiker dihapus dan pembuatnya dibina","s":5},{"t":"Menegur rekan agar menghapus dan berhenti menyebarkannya","s":4},{"t":"Menghapus stiker dari ponsel tanpa menegur","s":3},{"t":"Menyimpannya karena desainnya menarik","s":2},{"t":"Ikut menyebarkan ke grup lain","s":1}], "ex":"Simbol kelompok ekstrem dalam bentuk apa pun tidak boleh beredar di lingkungan kerja; laporkan agar ditertibkan."},
{"id":"TKP-4347", "q":"Anda diminta menjadi narasumber webinar, tetapi panitianya diketahui berafiliasi dengan gerakan pengusung khilafah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan afiliasi panitia itu ke pihak berwajib","s":5},{"t":"Menolak tawaran dengan tegas","s":4},{"t":"Menerima tetapi hanya bicara topik netral","s":3},{"t":"Menerima karena butuh jam terbang narasumber","s":2},{"t":"Menerima dan menyampaikan materi sesuai agenda mereka","s":1}], "ex":"Menjadi narasumber acara afiliasi gerakan khilafah memberi legitimasi pada mereka; tolak dan laporkan."},
{"id":"TKP-4348", "q":"Seorang pengguna media sosial mengancam akan melakukan aksi teror di kantor Anda melalui pesan langsung. Tindakan Anda?", "opts":[{"t":"Segera melaporkan ancaman itu ke pihak keamanan dan kepolisian","s":5},{"t":"Meneruskan ancaman itu ke atasan dan bagian keamanan kantor","s":4},{"t":"Menghapus pesan dan memblokir pengirimnya","s":3},{"t":"Mengabaikan karena menganggap hanya gertakan","s":2},{"t":"Membalas tantangannya agar ia membuktikan","s":1}], "ex":"Ancaman teror sekecil apa pun harus segera dilaporkan ke keamanan dan polisi; jangan pernah menganggapnya gertakan."},
{"id":"TKP-4349", "q":"Teman lama mengajak Anda investasi di platform yang ternyata menghimpun dana untuk jaringan radikal dengan iming-iming keuntungan besar. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan platform itu ke pihak berwajib","s":5},{"t":"Menolak dan memperingatkan teman tentang bahaya terlibat pendanaan jaringan radikal","s":4},{"t":"Menolak dengan alasan tidak punya modal","s":3},{"t":"Ikut dengan modal kecil sambil mengamati","s":2},{"t":"Ikut berinvestasi karena iming-iming keuntungannya besar","s":1}], "ex":"Platform investasi penghimpun dana jaringan radikal menjerat investornya secara hukum; tolak dan laporkan."},
{"id":"TKP-4350", "q":"Di siaran langsung jualan daring, penjual menyisipkan ceramah intoleran yang menghasut membenci kelompok lain di sela promosi. Anda penontonnya. Sikap Anda?", "opts":[{"t":"Melaporkan siaran itu ke platform dan berhenti menonton","s":5},{"t":"Melaporkan konten hasutannya ke platform","s":4},{"t":"Melewati bagian ceramah dan tetap menonton jualannya","s":3},{"t":"Tetap menonton karena barangnya murah","s":2},{"t":"Ikut menyimak ceramahnya dan membagikan siaran itu","s":1}], "ex":"Sisipan ceramah intoleran di siaran jualan adalah penyebaran kebencian berkedok dagang; laporkan ke platform."},
{"id":"TKP-4351", "q":"Rekan kerja mengajak Anda patungan donasi kripto ke dompet digital yang ternyata milik jaringan pendanaan kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan dompet digital itu ke pihak berwajib","s":5},{"t":"Menolak dan memperingatkan rekan tentang bahaya mendanai jaringan ekstrem","s":4},{"t":"Menolak dengan alasan tidak paham kripto","s":3},{"t":"Ikut patungan kecil agar tidak dicurigai rekan","s":2},{"t":"Ikut patungan karena diajak rekan dekat","s":1}], "ex":"Donasi kripto ke jaringan ekstrem adalah tindak pidana pendanaan terorisme; tolak dan laporkan dompetnya."},
{"id":"TKP-4352", "q":"Anda menerima transfer e-wallet dari nomor tak dikenal disertai pesan terima kasih atas dukungan perjuangan khilafah. Tindakan Anda?", "opts":[{"t":"Tidak memakai dana itu dan melaporkannya ke pihak berwajib","s":5},{"t":"Mengembalikan dana dan memblokir nomor pengirim","s":4},{"t":"Mengabaikan pesan dan tidak memakai dananya","s":3},{"t":"Memakai dananya karena menganggap rezeki nomplok","s":2},{"t":"Memakai dana dan menghubungi pengirim untuk kerja sama","s":1}], "ex":"Transfer misterius berkedok dukungan khilafah berpotensi menjerat penerima; jangan dipakai dan laporkan ke berwajib."},
{"id":"TKP-4353", "q":"Sebuah yayasan menggalang dana bencana lewat QRIS, tetapi Anda tahu pengelolanya terafiliasi jaringan radikal. Sikap Anda?", "opts":[{"t":"Tidak berdonasi dan melaporkan yayasan itu ke pihak berwajib","s":5},{"t":"Tidak berdonasi dan memperingatkan kerabat agar waspada","s":4},{"t":"Tidak berdonasi tanpa memberitahu siapa pun","s":3},{"t":"Berdonasi kecil karena kasihan pada korban bencana","s":2},{"t":"Berdonasi dan mengajak orang lain ikut berdonasi","s":1}], "ex":"Galang dana bencana berkedok yayasan afiliasi radikal harus dihindari dan dilaporkan; salurkan donasi lewat lembaga resmi."},
{"id":"TKP-4354", "q":"Teman menawarkan jasa penukaran kripto ke tunai dengan kurs menggiurkan, belakangan Anda tahu dananya berasal dari jaringan teror. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan jasa penukaran itu ke pihak berwajib","s":5},{"t":"Menolak dan memutus kontak dengan teman tersebut","s":4},{"t":"Menolak dengan alasan tidak butuh","s":3},{"t":"Mencoba sekali dengan nominal kecil","s":2},{"t":"Memakai jasanya karena kursnya menggiurkan","s":1}], "ex":"Penukaran dana jaringan teror adalah pencucian uang terorisme; tolak dan laporkan, jangan tergiur kurs."},
{"id":"TKP-4355", "q":"Di grup arisan daring, admin mengarahkan sebagian iuran untuk disumbangkan ke front perjuangan yang terafiliasi kelompok ekstrem. Anda anggota grup. Sikap Anda?", "opts":[{"t":"Menolak, keluar dari grup, dan melaporkan admin ke pihak berwajib","s":5},{"t":"Menolak iuran tambahan itu dan memprotes di grup","s":4},{"t":"Keluar dari grup tanpa protes","s":3},{"t":"Tetap ikut arisan asal iuran pokok tidak naik","s":2},{"t":"Setuju dan ikut menyumbang ke front tersebut","s":1}], "ex":"Arisan yang dananya dialirkan ke front afiliasi ekstrem harus ditinggalkan dan adminnya dilaporkan."},
{"id":"TKP-4356", "q":"Anda diminta menjadi perantara menerima paket kripto lalu meneruskannya ke beberapa dompet dengan imbalan fee. Pengirimnya tidak jelas dan menyebut ini untuk perjuangan kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tawaran itu ke pihak kepolisian","s":5},{"t":"Menolak tegas dan memblokir kontak pengirim","s":4},{"t":"Menolak dengan alasan sibuk","s":3},{"t":"Menerima sekali untuk melihat seberapa besar fee-nya","s":2},{"t":"Menerima karena fee-nya besar dan caranya mudah","s":1}], "ex":"Menjadi perantara transfer kripto tak jelas untuk perjuangan adalah money mule terorisme; tolak dan laporkan ke polisi."},
{"id":"TKP-4357", "q":"Sebuah toko daring milik kenalan Anda menjual merchandise bersimbol kelompok ekstrem dan keuntungannya untuk pendanaan mereka. Sikap Anda?", "opts":[{"t":"Tidak membeli dan melaporkan toko itu ke platform serta pihak berwajib","s":5},{"t":"Menasihati kenalan agar berhenti menjual merchandise terlarang","s":4},{"t":"Tidak membeli tanpa menegur","s":3},{"t":"Membeli satu karena desainnya bagus, tidak peduli simbolnya","s":2},{"t":"Membeli dan mempromosikan tokonya","s":1}], "ex":"Merchandise simbol kelompok ekstrem adalah propaganda sekaligus pendanaan; laporkan toko dan jangan membeli."},
{"id":"TKP-4358", "q":"Panitia pengajian meminta sumbangan via transfer ke rekening pribadi dengan dalih untuk dakwah, tetapi Anda curiga dananya untuk jaringan radikal. Sikap Anda?", "opts":[{"t":"Tidak menyumbang dan melaporkan kecurigaan itu ke pihak berwajib","s":5},{"t":"Meminta laporan keuangan resmi sebelum memutuskan menyumbang","s":4},{"t":"Tidak menyumbang tanpa menjelaskan alasan","s":3},{"t":"Menyumbang sedikit agar tidak dicap pelit","s":2},{"t":"Menyumbang dan mengajak jamaah lain ikut","s":1}], "ex":"Sumbangan dakwah ke rekening pribadi yang mencurigakan harus ditolak; minta akuntabilitas dan laporkan bila terindikasi radikal."},
{"id":"TKP-4359", "q":"Anda menemukan aplikasi dompet digital palsu yang dipakai mengumpulkan donasi untuk aksi teror berkedok amal. Tindakan Anda?", "opts":[{"t":"Melaporkan aplikasi itu ke pihak berwajib dan menyebarkan peringatan","s":5},{"t":"Melaporkan aplikasi palsu itu ke toko aplikasi","s":4},{"t":"Menghapus aplikasi tanpa melapor","s":3},{"t":"Membiarkan karena tidak menggunakannya","s":2},{"t":"Mengunduhnya karena penasaran","s":1}], "ex":"Aplikasi dompet palsu penghimpun dana teror harus dilaporkan ke berwajib agar diblokir dan pelakunya ditangkap."},
{"id":"TKP-4360", "q":"Saudara Anda meminjam KTP dan rekening Anda untuk menerima donasi yang ternyata untuk jaringan ekstrem, dengan imbalan uang jajan. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan saudara ke pihak berwajib demi keselamatannya","s":5},{"t":"Menolak tegas dan menasihatinya agar keluar dari jaringan itu","s":4},{"t":"Menolak dengan alasan takut ketahuan orang tua","s":3},{"t":"Menerima dengan syarat namanya tidak disebut","s":2},{"t":"Menerima demi imbalan uang jajan","s":1}], "ex":"Meminjamkan identitas untuk donasi jaringan ekstrem menjerat Anda sebagai pelaku; tolak dan selamatkan saudara dengan melapor."},
{"id":"TKP-4361", "q":"Di tempat kerja, beredar proposal sponsor kegiatan yang dananya berasal dari perusahaan cangkang milik jaringan radikal. Anda diminta menandatangani persetujuan. Sikap Anda?", "opts":[{"t":"Menolak menandatangani dan melaporkan ke pimpinan serta pihak berwajib","s":5},{"t":"Menolak dan meminta verifikasi legalitas sumber dana","s":4},{"t":"Menunda tanda tangan dengan alasan perlu kajian","s":3},{"t":"Menandatangani karena sudah disetujui rekan lain","s":2},{"t":"Menandatangani agar kegiatan cepat berjalan","s":1}], "ex":"Dana sponsor dari perusahaan cangkang jaringan radikal mencemari institusi; tolak tanda tangan dan laporkan."},
{"id":"TKP-4362", "q":"Anda melihat postingan lelang barang sitaan amal yang hasilnya disalurkan ke panti asuhan binaan kelompok ekstrem penganut paham khilafah. Sikap Anda?", "opts":[{"t":"Tidak ikut lelang dan melaporkan indikasi itu ke pihak berwajib","s":5},{"t":"Tidak ikut dan memperingatkan teman agar waspada","s":4},{"t":"Tidak ikut tanpa berkomentar","s":3},{"t":"Ikut lelang karena barangnya menarik","s":2},{"t":"Ikut lelang dan memenangkan barangnya","s":1}], "ex":"Lelang amal yang dananya ke binaan kelompok ekstrem adalah pendanaan terselubung; hindari dan laporkan."},
{"id":"TKP-4363", "q":"Seorang donatur menawarkan hibah besar ke instansi Anda dengan syarat mempekerjakan orang-orang dari kelompok intolerannya. Sikap Anda sebagai pejabat pengelola hibah?", "opts":[{"t":"Menolak hibah dan melaporkan syarat diskriminatif itu ke pimpinan","s":5},{"t":"Menolak syaratnya dan menawarkan kerja sama yang bersih","s":4},{"t":"Menunda keputusan sambil berkonsultasi","s":3},{"t":"Menerima hibah tetapi mengabaikan syaratnya diam-diam","s":2},{"t":"Menerima hibah beserta syaratnya","s":1}], "ex":"Hibah bersyarat rekrutmen kelompok intoleran adalah penyusupan; tolak dan laporkan ke pimpinan."},
{"id":"TKP-4364", "q":"Teman sekantor mengajak investasi NFT yang keuntungannya diklaim untuk mendanai perjuangan menegakkan khilafah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan skema itu ke pihak berwajib","s":5},{"t":"Menolak dan menjelaskan bahwa itu pendanaan paham terlarang","s":4},{"t":"Menolak karena tidak paham NFT","s":3},{"t":"Ikut dengan modal kecil untuk coba-coba","s":2},{"t":"Ikut berinvestasi karena tertarik keuntungannya","s":1}], "ex":"Investasi berkedok NFT untuk perjuangan khilafah adalah pendanaan jaringan; tolak dan laporkan."},
{"id":"TKP-4365", "q":"Kas RT Anda diminta iurannya dinaikkan untuk disumbangkan ke ormas yang baru dibubarkan pemerintah karena paham ekstremnya. Anda warga RT itu. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke ketua RT serta pihak berwenang","s":5},{"t":"Menolak membayar kenaikan iuran tersebut","s":4},{"t":"Tidak membayar tanpa protes","s":3},{"t":"Membayar agar tidak ribut dengan tetangga","s":2},{"t":"Membayar dan mendukung sumbangan itu","s":1}], "ex":"Kas warga tidak boleh dialirkan ke ormas terlarang berpaham ekstrem; tolak dan laporkan."},
{"id":"TKP-4366", "q":"Anda menjadi bendahara acara dan menemukan aliran dana janggal ke rekening yang terindikasi milik jaringan teror. Tindakan Anda?", "opts":[{"t":"Menghentikan aliran dana dan melaporkannya ke pihak berwajib","s":5},{"t":"Menanyakan kejelasan aliran dana itu ke ketua panitia","s":4},{"t":"Mencatatnya saja tanpa menindaklanjuti","s":3},{"t":"Membiarkan karena bukan wewenang Anda mengusut","s":2},{"t":"Menutupinya agar acara tidak gagal","s":1}], "ex":"Bendahara yang menemukan aliran dana ke jaringan teror wajib menghentikan dan melaporkannya ke berwajib."},
{"id":"TKP-4367", "q":"Sebuah platform crowdfunding menampung proyek kemanusiaan yang ternyata front penggalangan dana kelompok radikal. Anda sudah berdonasi. Sikap Anda?", "opts":[{"t":"Melaporkan proyek itu ke platform dan pihak berwajib serta meminta donasi ditarik","s":5},{"t":"Melaporkan proyek mencurigakan itu ke pengelola platform","s":4},{"t":"Berhenti berdonasi tanpa melapor","s":3},{"t":"Membiarkan karena donasi sudah terlanjur","s":2},{"t":"Menambah donasi karena merasa proyeknya mulia","s":1}], "ex":"Crowdfunding front kelompok radikal harus dilaporkan ke platform dan berwajib; minta penarikan donasi Anda."},
{"id":"TKP-4368", "q":"Atasan meminta Anda memproses pencairan dana bansos ke rekening-rekening yang Anda curigai milik jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Menolak memproses dan melaporkan kecurigaan ke inspektorat","s":5},{"t":"Menolak dan meminta verifikasi daftar penerima terlebih dahulu","s":4},{"t":"Menunda pemrosesan dengan alasan administrasi","s":3},{"t":"Memproses karena perintah atasan","s":2},{"t":"Memproses dan mempercepat pencairannya","s":1}], "ex":"Perintah atasan menyalurkan bansos ke jaringan ekstrem wajib ditolak dan dilaporkan ke inspektorat."},
{"id":"TKP-4369", "q":"Kenalan Anda membuka jasa titip transfer ke luar negeri dengan tarif murah untuk menghindari pelacakan, dipakai jaringan radikal. Ia menawarkan Anda jadi agen. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan jasa ilegal itu ke pihak berwajib","s":5},{"t":"Menolak dan memperingatkan bahaya terlibat transfer gelap","s":4},{"t":"Menolak dengan halus","s":3},{"t":"Menerima sebagai agen sambilan","s":2},{"t":"Menerima dan merekrut agen lain","s":1}], "ex":"Jasa transfer gelap untuk jaringan radikal adalah tindak pidana; tolak tawaran agen dan laporkan."},
{"id":"TKP-4370", "q":"Masjid di kompleks Anda mengedarkan kupon qurban dengan harga jauh di bawah pasar, dan dananya disalurkan ke kelompok pengusung paham khilafah. Sikap Anda?", "opts":[{"t":"Tidak membeli kupon dan melaporkan ke pengurus serta pihak berwajib","s":5},{"t":"Tidak membeli dan memberitahu jamaah lain agar waspada","s":4},{"t":"Tidak membeli tanpa berkomentar","s":3},{"t":"Membeli karena harganya murah","s":2},{"t":"Membeli banyak dan membantu menjualkannya","s":1}], "ex":"Kupon qurban murah yang dananya ke pengusung khilafah adalah modus pendanaan; jangan beli dan laporkan."},
{"id":"TKP-4371", "q":"Anda ditawari menjadi buzzer berbayar untuk menyebarkan tagar dukungan pada kelompok ekstrem dengan bayaran per postingan. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tawaran itu ke pihak berwajib","s":5},{"t":"Menolak tegas tawaran buzzer tersebut","s":4},{"t":"Mengabaikan tawaran itu","s":3},{"t":"Mempertimbangkan karena bayarannya lumayan","s":2},{"t":"Menerima tawaran demi bayaran","s":1}], "ex":"Buzzer berbayar pendukung kelompok ekstrem adalah corong propaganda; tolak dan laporkan penawarnya."},
{"id":"TKP-4372", "q":"Sebuah koperasi simpan pinjam menawarkan bagi hasil fantastis, belakangan diketahui dananya diputar untuk jaringan teror. Anda sudah menjadi anggota. Sikap Anda?", "opts":[{"t":"Menarik dana, keluar, dan melaporkan koperasi itu ke pihak berwajib","s":5},{"t":"Menarik dana dan memperingatkan anggota lain","s":4},{"t":"Menarik dana secara diam-diam","s":3},{"t":"Tetap menjadi anggota karena bagi hasilnya besar","s":2},{"t":"Menambah simpanan karena iming-iming bagi hasil","s":1}], "ex":"Koperasi yang dananya diputar untuk jaringan teror harus ditinggalkan dan dilaporkan ke berwajib."},
{"id":"TKP-4373", "q":"Teman Anda meminta tolong membuatkan laporan keuangan fiktif untuk menutupi aliran donasi ke jaringan radikal. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan permintaan itu ke pihak berwajib","s":5},{"t":"Menolak tegas dan menasihatinya agar berhenti","s":4},{"t":"Menolak dengan alasan tidak bisa akuntansi","s":3},{"t":"Membantu sebagian karena kasihan","s":2},{"t":"Membantu membuatkan laporan fiktifnya","s":1}], "ex":"Laporan keuangan fiktif penutup donasi jaringan radikal adalah kejahatan; tolak dan laporkan."},
{"id":"TKP-4374", "q":"Di acara keluarga, saudara memamerkan keuntungan dari bisnis yang dananya ia akui untuk perjuangan kelompok ekstrem. Sikap Anda?", "opts":[{"t":"Menasihatinya berhenti dan melaporkan ke pihak berwajib","s":5},{"t":"Menasihati agar keluar dari bisnis tersebut","s":4},{"t":"Diam agar acara keluarga tidak rusak","s":3},{"t":"Meminta diajari cara ikut bisnisnya","s":2},{"t":"Ikut menanam modal di bisnisnya","s":1}], "ex":"Bisnis pendanaan kelompok ekstrem harus dihentikan; nasihati saudara dan laporkan ke berwajib."},
{"id":"TKP-4375", "q":"Sebuah aplikasi gim menawarkan hadiah saldo bagi pemain yang menyebarkan kode referral berisi ajakan bergabung ke komunitas ekstrem. Anda pemain gim itu. Sikap Anda?", "opts":[{"t":"Tidak menyebar, melaporkan fitur itu ke pengembang dan pihak berwajib","s":5},{"t":"Tidak menyebar dan melaporkan ke pengembang gim","s":4},{"t":"Mengabaikan tawaran hadiahnya","s":3},{"t":"Menyebar ke sedikit teman demi hadiah saldo","s":2},{"t":"Menyebar seluas-luasnya demi hadiah besar","s":1}], "ex":"Hadiah gim berkedok penyebaran ajakan komunitas ekstrem adalah rekrutmen terselubung; laporkan ke pengembang dan berwajib."},
{"id":"TKP-4376", "q":"Seorang dai di media sosial yang Anda ikuti mulai menyelipkan ceramah bahwa sistem khilafah wajib ditegakkan dan demokrasi harus ditinggalkan. Sikap Anda sebagai pengikutnya?", "opts":[{"t":"Berhenti mengikuti, melaporkan kontennya, dan memperingatkan jamaah lain","s":5},{"t":"Berhenti mengikuti dan melaporkan akunnya","s":4},{"t":"Berhenti mengikuti secara diam-diam","s":3},{"t":"Tetap mengikuti karena ceramah lainnya bagus","s":2},{"t":"Tetap mengikuti dan membagikan ceramah khilafahnya","s":1}], "ex":"Dakwah yang menyelipkan agenda khilafah harus ditinggalkan dan dilaporkan agar tidak menyesatkan jamaah lain."},
{"id":"TKP-4377", "q":"Pengajian rutin di lingkungan Anda diganti pematerinya dengan ustaz yang mengajarkan kebencian intoleran terhadap pemerintah yang sah. Anda jamaah rutin. Sikap Anda?", "opts":[{"t":"Berhenti hadir dan melaporkan materi intolerannya ke pengurus serta pihak berwenang","s":5},{"t":"Mengusulkan ke pengurus agar pemateri dikembalikan seperti semula","s":4},{"t":"Berhenti hadir tanpa protes","s":3},{"t":"Tetap hadir karena segan dengan tetangga","s":2},{"t":"Makin rajin hadir karena merasa tercerahkan","s":1}], "ex":"Pengajian yang mengajarkan kebencian intoleran terhadap pemerintah sah harus ditinggalkan dan dilaporkan."},
{"id":"TKP-4378", "q":"Teman mengajak Anda ke majelis taklim yang ternyata mewajibkan anggotanya berbaiat setia pada kepemimpinan khilafah. Sikap Anda?", "opts":[{"t":"Menolak baiat dan melaporkan majelis itu ke pihak berwajib","s":5},{"t":"Menolak dan memperingatkan teman yang mengajak","s":4},{"t":"Menolak dengan alasan sibuk","s":3},{"t":"Ikut hadir tetapi menolak berbaiat","s":2},{"t":"Berbaiat karena sudah telanjur diajak teman","s":1}], "ex":"Majelis taklim berkedok baiat khilafah adalah rekrutmen jaringan; tolak dan laporkan ke berwajib."},
{"id":"TKP-4379", "q":"Khotbah Jumat di masjid dekat kantor Anda berisi hasutan ekstrem mengajak jamaah memusuhi kelompok berbeda keyakinan. Anda jamaah di sana. Sikap Anda?", "opts":[{"t":"Melaporkan isi khotbah itu ke takmir masjid dan pihak berwenang","s":5},{"t":"Menegur khatib seusai salat agar tidak menghasut","s":4},{"t":"Pindah masjid tanpa melapor","s":3},{"t":"Tetap salat di sana karena dekat kantor","s":2},{"t":"Mendukung isi khotbah dan menyebarkannya","s":1}], "ex":"Mimbar Jumat tidak boleh dipakai untuk hasutan ekstrem dan intoleran; laporkan ke takmir dan berwenang."},
{"id":"TKP-4380", "q":"Sebuah kanal podcast dakwah populer yang Anda dengarkan mulai mengundang narasumber penganjur teror dan khilafah. Sikap Anda?", "opts":[{"t":"Berhenti mendengarkan dan melaporkan kanal itu ke platform","s":5},{"t":"Berhenti mendengarkan dan memberi ulasan peringatan","s":4},{"t":"Melewati episode dengan narasumber tersebut","s":3},{"t":"Tetap mendengarkan semua episodenya","s":2},{"t":"Membagikan episodenya karena narasumbernya terkenal","s":1}], "ex":"Podcast dakwah yang mengundang penganjur teror memberi panggung pada ekstremisme; tinggalkan dan laporkan."},
{"id":"TKP-4381", "q":"Anak Anda pulang dari pesantren kilat dan bercerita diajari bahwa hormat bendera itu syirik menurut paham khilafah. Sikap Anda sebagai orang tua?", "opts":[{"t":"Melaporkan penyelenggara pesantren kilat itu ke pihak berwenang","s":5},{"t":"Menarik anak dari kegiatan itu dan meluruskan pemahamannya","s":4},{"t":"Menasihati anak agar tidak mengikuti ajaran itu","s":3},{"t":"Membiarkan karena menganggap itu perbedaan tafsir","s":2},{"t":"Mendukung ajarannya karena disampaikan ustaz","s":1}], "ex":"Ajaran bahwa hormat bendera itu syirik adalah doktrin khilafah; tarik anak dan laporkan penyelenggaranya."},
{"id":"TKP-4382", "q":"Grup keluarga besar Anda disusupi ceramah berantai bernada ekstrem yang mengajarkan anak-anak membenci pemerintah dan aparat sebagai thaghut. Anda anggota grup. Sikap Anda?", "opts":[{"t":"Memprotes di grup, mengeluarkan penyebar, dan melaporkan bila menghasut","s":5},{"t":"Menegur penyebar agar berhenti mengirim ceramah hasutan","s":4},{"t":"Membisukan grup tanpa protes","s":3},{"t":"Membiarkan karena tidak enak dengan keluarga","s":2},{"t":"Ikut meneruskan ceramahnya ke grup lain","s":1}], "ex":"Ceramah hasutan anti-pemerintah di grup keluarga meracuni semua usia; tegur, keluarkan penyebar, laporkan bila perlu."},
{"id":"TKP-4383", "q":"Seorang tokoh agama di daerah Anda terang-terangan mendeklarasikan dukungan pada sistem khilafah dan menolak Pancasila dalam ceramahnya. Sikap Anda sebagai warga?", "opts":[{"t":"Melaporkan deklarasi itu ke pihak berwajib","s":5},{"t":"Tidak menghadiri lagi ceramah tokoh tersebut","s":4},{"t":"Menganggapnya sekadar retorika tokoh agama","s":3},{"t":"Tetap menghadiri karena ia tokoh dihormati","s":2},{"t":"Mendukung deklarasinya","s":1}], "ex":"Deklarasi penolakan Pancasila demi khilafah oleh tokoh agama adalah pelanggaran hukum; laporkan ke berwajib."},
{"id":"TKP-4384", "q":"Teman Anda membuka kelas daring berbayar yang materinya doktrin intoleran dan perekrutan jaringan khilafah. Ia mengajak Anda jadi afiliator. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan kelas daring itu ke pihak berwajib","s":5},{"t":"Menolak tawaran afiliator dengan tegas","s":4},{"t":"Mengabaikan tawarannya","s":3},{"t":"Mendaftar sebagai peserta karena penasaran","s":2},{"t":"Menerima jadi afiliator demi komisi","s":1}], "ex":"Kelas daring doktrin intoleran adalah bisnis radikalisasi; tolak dan laporkan ke berwajib."},
{"id":"TKP-4385", "q":"Di acara pernikahan, penceramah tamu menyelipkan ajakan bergabung ke gerakan khilafah di depan ratusan tamu. Anda salah satu tamu. Sikap Anda?", "opts":[{"t":"Melaporkan penceramah itu ke panitia dan pihak berwenang","s":5},{"t":"Memprotes langsung agar ceramah kembali ke tema pernikahan","s":4},{"t":"Mengabaikan dan fokus menikmati acara","s":3},{"t":"Mendengarkan dengan saksama karena tertarik","s":2},{"t":"Mencatat kontaknya untuk bergabung","s":1}], "ex":"Acara pernikahan bukan panggung ajakan khilafah; protes dan laporkan penceramah yang menyalahgunakannya."},
{"id":"TKP-4386", "q":"Buletin Jumat masjid kantor Anda memuat artikel yang memuji aksi teror sebagai perjuangan mulia. Anda karyawan di sana. Sikap Anda?", "opts":[{"t":"Melaporkan buletin itu ke takmir dan pimpinan kantor","s":5},{"t":"Meminta takmir menarik dan mengganti buletin tersebut","s":4},{"t":"Membuang buletin tanpa melapor","s":3},{"t":"Membacanya sekilas lalu mengabaikan","s":2},{"t":"Menyimpan dan menyebarkannya ke rekan","s":1}], "ex":"Buletin yang memuji aksi teror adalah propaganda; laporkan ke takmir dan pimpinan agar ditarik dan pelakunya dibina."},
{"id":"TKP-4387", "q":"Anak remaja Anda mengikuti komunitas hijrah daring yang ternyata mengarahkannya pada paham ekstrem dan rencana baiat khilafah. Sikap Anda?", "opts":[{"t":"Melaporkan komunitas itu, memutus akses anak, dan memberinya pembinaan","s":5},{"t":"Melarang anak ikut komunitas itu dan menjelaskan bahayanya","s":4},{"t":"Mengawasi diam-diam tanpa melarang","s":3},{"t":"Membiarkan karena menganggap hijrah itu positif","s":2},{"t":"Mendukungnya karena anak jadi lebih religius","s":1}], "ex":"Komunitas hijrah yang mengarah ke baiat khilafah membahayakan remaja; putus aksesnya, bina anak, laporkan komunitasnya."},
{"id":"TKP-4388", "q":"Seorang dai kondang menggalang dana umat untuk membangun pusat dakwah yang ternyata menjadi markas kaderisasi kelompok ekstrem. Anda donaturnya. Sikap Anda?", "opts":[{"t":"Menghentikan donasi dan melaporkan ke pihak berwajib","s":5},{"t":"Menghentikan donasi dan meminta pertanggungjawaban","s":4},{"t":"Berhenti berdonasi diam-diam","s":3},{"t":"Tetap berdonasi karena bangunannya sudah berjalan","s":2},{"t":"Menambah donasi dan mengajak jamaah lain","s":1}], "ex":"Pusat dakwah berkedok markas kaderisasi ekstrem harus dihentikan pendanaannya dan dilaporkan ke berwajib."},
{"id":"TKP-4389", "q":"Tetangga mengajak Anda menghadiri tabligh akbar yang spanduknya terang-terangan menyerukan penegakan khilafah dan penolakan demokrasi. Sikap Anda?", "opts":[{"t":"Menolak hadir dan melaporkan acara itu ke pihak berwenang","s":5},{"t":"Menolak ajakan dengan tegas","s":4},{"t":"Menolak dengan alasan ada keperluan","s":3},{"t":"Hadir sekadar melihat-lihat","s":2},{"t":"Hadir dan ikut menyerukan","s":1}], "ex":"Tabligh akbar berspanduk seruan khilafah adalah kampanye paham terlarang; jangan hadiri dan laporkan."},
{"id":"TKP-4390", "q":"Guru ngaji anak Anda mengajarkan bahwa berteman dengan nonmuslim dilarang dan negara ini harus diganti khilafah. Sikap Anda sebagai orang tua murid?", "opts":[{"t":"Melaporkan guru itu ke pengelola dan pihak berwenang","s":5},{"t":"Menghentikan anak les dan mencari guru pengganti","s":4},{"t":"Menasihati anak agar tidak mengikuti ajaran itu","s":3},{"t":"Membiarkan karena menghormati guru","s":2},{"t":"Mendukung ajarannya sebagai bentuk ketegasan akidah","s":1}], "ex":"Guru ngaji penyebar intoleransi dan doktrin khilafah merusak anak; hentikan lesnya dan laporkan."},
{"id":"TKP-4391", "q":"Sebuah penerbit buku agama yang Anda kenal menerbitkan buku anak yang menyisipkan doktrin kebencian intoleran. Sikap Anda?", "opts":[{"t":"Melaporkan penerbit itu ke pihak berwajib","s":5},{"t":"Tidak membeli dan memperingatkan orang tua lain","s":4},{"t":"Tidak membeli bukunya","s":3},{"t":"Membeli karena ilustrasinya bagus","s":2},{"t":"Membeli dan membagikan ke anak-anak","s":1}], "ex":"Buku anak penyisip doktrin kebencian intoleran meracuni generasi; jangan beli dan laporkan penerbitnya."},
{"id":"TKP-4392", "q":"Dalam zikir akbar, pembawa acara mengajak jamaah bersumpah setia menegakkan khilafah. Anda jamaah di sana. Sikap Anda?", "opts":[{"t":"Tidak ikut bersumpah dan melaporkan kejadian itu ke pihak berwenang","s":5},{"t":"Tidak ikut bersumpah dan meninggalkan lokasi","s":4},{"t":"Diam saja di tempat","s":3},{"t":"Ikut bersumpah karena terbawa suasana","s":2},{"t":"Ikut bersumpah dengan penuh semangat","s":1}], "ex":"Ajakan sumpah setia khilafah di forum zikir adalah baiat terselubung; jangan ikuti dan laporkan."},
{"id":"TKP-4393", "q":"Kanal dakwah favorit Anda menjual merchandise yang keuntungannya terang-terangan untuk perjuangan khilafah. Sikap Anda?", "opts":[{"t":"Berhenti mendukung kanal itu dan melaporkannya","s":5},{"t":"Berhenti membeli merchandise dan berhenti mengikuti","s":4},{"t":"Tidak membeli tanpa berhenti mengikuti","s":3},{"t":"Tetap membeli karena desainnya bagus","s":2},{"t":"Membeli banyak untuk mendukung perjuangannya","s":1}], "ex":"Merchandise pendanaan perjuangan khilafah adalah donasi untuk paham terlarang; tinggalkan kanalnya dan laporkan."},
{"id":"TKP-4394", "q":"Ustaz di lingkungan Anda melarang jamaah memilih dalam pemilu dengan alasan demokrasi itu sistem kafir menurut paham khilafah. Sikap Anda?", "opts":[{"t":"Tetap menggunakan hak pilih dan melaporkan hasutan golput itu","s":5},{"t":"Tetap memilih dan mengajak warga lain tidak terpengaruh","s":4},{"t":"Tetap memilih tanpa melapor","s":3},{"t":"Golput agar tidak dimusuhi jamaah","s":2},{"t":"Golput dan ikut menyebarkan larangannya","s":1}], "ex":"Hasutan golput atas nama paham khilafah merusak demokrasi; gunakan hak pilih dan laporkan penghasutnya."},
{"id":"TKP-4395", "q":"Sebuah biro umrah menawarkan paket murah dengan syarat jamaah mengikuti pembinaan ideologi khilafah sebelum berangkat. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan biro itu ke pihak berwenang","s":5},{"t":"Menolak tawaran dan memilih biro resmi","s":4},{"t":"Menolak dengan alasan jadwal tidak cocok","s":3},{"t":"Menerima karena paketnya murah","s":2},{"t":"Menerima dan mengajak keluarga ikut","s":1}], "ex":"Biro umrah berkedok pembinaan khilafah menodai ibadah; tolak dan laporkan ke berwenang."},
{"id":"TKP-4396", "q":"Teman Anda menjadi relawan kemanusiaan di daerah konflik dan pulang membawa paham ekstrem serta ajakan berjihad dengan kekerasan. Sikap Anda?", "opts":[{"t":"Melaporkan indikasi itu ke pihak berwajib demi keamanannya","s":5},{"t":"Menasihatinya agar tidak menyebarkan paham kekerasan","s":4},{"t":"Menjaga jarak tanpa melapor","s":3},{"t":"Mendengarkan ceritanya dengan antusias","s":2},{"t":"Tertarik ikut menjadi relawan bersamanya","s":1}], "ex":"Relawan yang pulang membawa paham kekerasan perlu dibina dan dilaporkan agar tidak menyebar ke lingkungan."},
{"id":"TKP-4397", "q":"Pengajian daring yang Anda ikuti mewajibkan peserta mengunggah video sumpah menolak Pancasila demi khilafah sebagai syarat naik level. Sikap Anda?", "opts":[{"t":"Keluar dan melaporkan pengajian itu ke pihak berwajib","s":5},{"t":"Keluar dan memperingatkan peserta lain","s":4},{"t":"Keluar diam-diam","s":3},{"t":"Mengunggah video agar bisa naik level","s":2},{"t":"Mengunggah video dan mengajak teman ikut","s":1}], "ex":"Sumpah menolak Pancasila sebagai syarat level adalah baiat digital khilafah; keluar dan laporkan."},
{"id":"TKP-4398", "q":"Seorang penceramah di TV lokal rutin menyampaikan ceramah intoleran yang merendahkan keyakinan lain. Anda penonton setianya. Sikap Anda?", "opts":[{"t":"Melaporkan program itu ke KPI dan berhenti menonton","s":5},{"t":"Berhenti menonton program tersebut","s":4},{"t":"Melewati segmen ceramahnya","s":3},{"t":"Tetap menonton karena sudah kebiasaan","s":2},{"t":"Mendukungnya dan menelepon interaktif","s":1}], "ex":"Ceramah intoleran di TV lokal melanggar penyiaran; laporkan ke KPI dan berhenti menonton."},
{"id":"TKP-4399", "q":"Komunitas motor Anda diajak touring amal yang ternyata titik kumpulnya dipakai orasi penegakan khilafah. Anda sudah di lokasi. Sikap Anda?", "opts":[{"t":"Meninggalkan lokasi dan melaporkan orasi itu","s":5},{"t":"Tidak ikut orasi dan pulang","s":4},{"t":"Menunggu orasi selesai di kejauhan","s":3},{"t":"Ikut mendengarkan orasi sampai selesai","s":2},{"t":"Ikut berorasi mendukung khilafah","s":1}], "ex":"Touring amal berkedok orasi khilafah harus ditinggalkan; jangan jadi massa pendukung dan laporkan."},
{"id":"TKP-4400", "q":"Saudara ipar Anda giat mengunggah konten yang mengkafirkan pemerintah dan mengajak pengikutnya mendukung teror. Sikap Anda sebagai keluarga?", "opts":[{"t":"Menasihati dengan tegas dan melaporkan kontennya ke pihak berwajib","s":5},{"t":"Menasihati agar berhenti menyebar konten pengkafiran","s":4},{"t":"Menghindarinya saat kumpul keluarga","s":3},{"t":"Membiarkan demi menjaga hubungan keluarga","s":2},{"t":"Ikut membagikan kontennya","s":1}], "ex":"Konten pengkafiran pendukung teror dari kerabat tetap harus dinasihati tegas dan dilaporkan ke berwajib."},
{"id":"TKP-4401", "q":"Sebagai petugas layanan, rekan Anda menolak melayani warga berbeda keyakinan dengan alasan intoleran bahwa mereka najis. Sikap Anda?", "opts":[{"t":"Melaporkan diskriminasi itu ke atasan agar ditindak tegas","s":5},{"t":"Menegur rekan dan mengambil alih pelayanan warga tersebut","s":4},{"t":"Melayani warga itu sendiri tanpa menegur rekan","s":3},{"t":"Membiarkan karena tidak ingin bermasalah dengan rekan","s":2},{"t":"Ikut menolak melayani dengan alasan yang sama","s":1}], "ex":"Penolakan layanan berbasis keyakinan adalah diskriminasi intoleran; laporkan agar pelakunya ditindak."},
{"id":"TKP-4402", "q":"Warga mengurus izin rumah ibadahnya dipersulit oknum petugas yang intoleran dan meminta pungutan liar. Anda petugas di dinas itu. Sikap Anda?", "opts":[{"t":"Melaporkan oknum itu ke atasan dan inspektorat","s":5},{"t":"Membantu warga mengurus izin sesuai prosedur yang benar","s":4},{"t":"Mengarahkan warga ke petugas lain","s":3},{"t":"Membiarkan karena takut dengan oknum tersebut","s":2},{"t":"Ikut mempersulit agar dapat bagian pungutan","s":1}], "ex":"Mempersulit izin rumah ibadah atas dasar intoleransi plus pungli adalah pelanggaran berat; laporkan ke inspektorat."},
{"id":"TKP-4403", "q":"Kepala seksi Anda memerintahkan agar layanan diprioritaskan untuk warga sekeyakinan dengannya yang intoleran terhadap lainnya. Sikap Anda?", "opts":[{"t":"Menolak perintah diskriminatif dan melaporkannya ke pimpinan","s":5},{"t":"Tetap melayani semua warga secara adil tanpa membeda-bedakan","s":4},{"t":"Mengikuti perintah agar tidak dimutasi","s":3},{"t":"Mengikuti perintah karena ia atasan","s":2},{"t":"Mendukung kebijakan itu secara terbuka","s":1}], "ex":"Perintah diskriminasi layanan berbasis keyakinan wajib ditolak; laporkan atasan ke pimpinan."},
{"id":"TKP-4404", "q":"Di puskesmas tempat Anda bekerja, seorang nakes menolak menangani pasien gawat darurat beda keyakinan karena alasan intoleran. Sikap Anda?", "opts":[{"t":"Mengambil alih penanganan pasien dan melaporkan nakes itu","s":5},{"t":"Menegur keras dan memastikan pasien segera ditangani","s":4},{"t":"Menangani pasien tanpa menegur nakes tersebut","s":3},{"t":"Membiarkan karena itu keputusan pribadinya","s":2},{"t":"Mendukung penolakannya","s":1}], "ex":"Penolakan layanan gawat darurat atas dasar intoleransi membahayakan nyawa; ambil alih dan laporkan pelakunya."},
{"id":"TKP-4405", "q":"Panitia seleksi pegawai di instansi Anda menggugurkan pelamar berprestasi hanya karena keyakinannya, atas arahan yang intoleran. Anda anggota panitia. Sikap Anda?", "opts":[{"t":"Menolak keputusan diskriminatif dan melaporkannya","s":5},{"t":"Memperjuangkan agar seleksi kembali objektif berbasis merit","s":4},{"t":"Diam agar tidak dianggap melawan panitia","s":3},{"t":"Menyetujui karena mayoritas panitia setuju","s":2},{"t":"Ikut menggugurkan dengan semangat","s":1}], "ex":"Diskriminasi keyakinan dalam seleksi pegawai melanggar meritokrasi; tolak dan laporkan."},
{"id":"TKP-4406", "q":"Sebagai guru, wali murid menuntut Anda memberi nilai rendah ke siswa beda keyakinan karena sentimen intoleran. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tekanan itu ke kepala sekolah","s":5},{"t":"Tetap memberi nilai objektif sesuai prestasi siswa","s":4},{"t":"Mengabaikan tuntutan tanpa melapor","s":3},{"t":"Menurunkan sedikit nilainya agar wali murid diam","s":2},{"t":"Menuruti tuntutan wali murid","s":1}], "ex":"Tekanan intoleran untuk mendiskriminasi nilai siswa harus ditolak; laporkan ke kepala sekolah."},
{"id":"TKP-4407", "q":"Oknum aparat di wilayah Anda membiarkan perusakan rumah ibadah oleh massa intoleran tanpa bertindak. Anda menyaksikannya. Sikap Anda?", "opts":[{"t":"Melaporkan pembiaran itu ke propam dan pimpinan yang lebih tinggi","s":5},{"t":"Mendokumentasikan kejadian sebagai bukti","s":4},{"t":"Menjauh dari lokasi demi keselamatan","s":3},{"t":"Menonton karena penasaran","s":2},{"t":"Ikut merusak karena terbawa massa","s":1}], "ex":"Pembiaran perusakan rumah ibadah oleh aparat adalah pelanggaran tugas; laporkan ke propam dengan bukti."},
{"id":"TKP-4408", "q":"Anda petugas dukcapil dan diminta rekan untuk mempersulit penerbitan KTP warga penghayat kepercayaan karena dianggap sesat oleh kelompok intoleran. Sikap Anda?", "opts":[{"t":"Menolak dan melayani sesuai prosedur serta melaporkan rekan","s":5},{"t":"Tetap menerbitkan dokumen sesuai hak warga","s":4},{"t":"Mengalihkan ke loket lain","s":3},{"t":"Menunda penerbitannya","s":2},{"t":"Menuruti permintaan rekan","s":1}], "ex":"Hak administrasi penghayat kepercayaan dilindungi konstitusi; tolak diskriminasi intoleran dan laporkan."},
{"id":"TKP-4409", "q":"Dalam musrenbang, usulan pembangunan fasilitas umum ditolak hanya karena pengusulnya dari kelompok minoritas yang dibenci kelompok intoleran. Anda peserta. Sikap Anda?", "opts":[{"t":"Memprotes penolakan diskriminatif dan melaporkannya","s":5},{"t":"Membela usulan agar dinilai dari manfaatnya","s":4},{"t":"Diam karena takut dimusuhi mayoritas","s":3},{"t":"Setuju dengan penolakan mayoritas","s":2},{"t":"Ikut menolak dengan berteriak","s":1}], "ex":"Penolakan usulan pembangunan berbasis sentimen intoleran merugikan publik; protes dan bela asas keadilan."},
{"id":"TKP-4410", "q":"Sebagai petugas imigrasi, Anda menemukan rekan meloloskan WNA yang terindikasi jaringan teror demi suap. Sikap Anda?", "opts":[{"t":"Melaporkan ke atasan dan pihak berwajib segera","s":5},{"t":"Menggagalkan pelolosan dan menahan dokumennya","s":4},{"t":"Menasihati rekan agar tidak mengulangi","s":3},{"t":"Membiarkan karena takut","s":2},{"t":"Ikut meminta bagian suap","s":1}], "ex":"Pelolosan WNA terindikasi jaringan teror demi suap membahayakan negara; laporkan segera ke berwajib."},
{"id":"TKP-4411", "q":"Sekolah tempat Anda mengajar didesak kelompok intoleran untuk mengeluarkan siswa yang orang tuanya beda keyakinan. Sikap Anda sebagai guru?", "opts":[{"t":"Menolak desakan dan melaporkan ke dinas pendidikan","s":5},{"t":"Membela hak siswa untuk tetap bersekolah","s":4},{"t":"Tidak ikut campur urusan yayasan","s":3},{"t":"Setuju demi menjaga nama baik sekolah","s":2},{"t":"Ikut mendesak pengeluaran siswa","s":1}], "ex":"Desakan intoleran mengeluarkan siswa melanggar hak pendidikan; tolak dan laporkan ke dinas pendidikan."},
{"id":"TKP-4412", "q":"Anda panitia bantuan sosial dan ada arahan agar bantuan hanya untuk warga sekeyakinan karena sentimen intoleran donatur. Sikap Anda?", "opts":[{"t":"Menolak arahan diskriminatif dan menyalurkan bantuan secara adil","s":5},{"t":"Menyalurkan bantuan ke semua yang membutuhkan tanpa kecuali","s":4},{"t":"Mundur dari kepanitiaan","s":3},{"t":"Mengikuti arahan demi kelancaran acara","s":2},{"t":"Mendukung arahan donatur","s":1}], "ex":"Bantuan sosial tidak boleh didiskriminasi atas dasar keyakinan; tolak arahan intoleran donatur."},
{"id":"TKP-4413", "q":"Sebagai petugas pajak, wajib pajak menawarkan gratifikasi agar laporannya yang mendanai jaringan ekstrem tidak diperiksa. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan ke atasan serta pihak berwajib","s":5},{"t":"Menolak gratifikasi dan tetap memeriksa sesuai prosedur","s":4},{"t":"Menolak gratifikasi tanpa melapor","s":3},{"t":"Menerima dan memperlambat pemeriksaan","s":2},{"t":"Menerima dan menghentikan pemeriksaan","s":1}], "ex":"Gratifikasi untuk menutupi pendanaan jaringan ekstrem adalah kejahatan ganda; tolak dan laporkan."},
{"id":"TKP-4414", "q":"Di kantor lurah, warga yang melapor tentang aktivitas kelompok radikal justru diintimidasi oknum yang simpatisan kelompok itu. Anda staf di sana. Sikap Anda?", "opts":[{"t":"Melindungi pelapor dan melaporkan oknum ke camat serta polisi","s":5},{"t":"Menampung laporan warga dan meneruskannya ke pihak berwajib","s":4},{"t":"Menyarankan warga melapor ke tempat lain","s":3},{"t":"Diam karena takut dengan oknum tersebut","s":2},{"t":"Ikut mengintimidasi pelapor","s":1}], "ex":"Pelapor aktivitas kelompok radikal wajib dilindungi; oknum pengintimidasi harus dilaporkan ke camat dan polisi."},
{"id":"TKP-4415", "q":"Anda anggota tim verifikasi ormas dan menemukan ormas pemohon menyebarkan paham khilafah serta intoleran. Pimpinan menekan agar diloloskan. Sikap Anda?", "opts":[{"t":"Menolak meloloskan dan melaporkan tekanan pimpinan","s":5},{"t":"Tetap memberi rekomendasi penolakan berbasis fakta","s":4},{"t":"Abstain dari pengambilan keputusan","s":3},{"t":"Meloloskan karena perintah pimpinan","s":2},{"t":"Meloloskan dan membela ormas itu","s":1}], "ex":"Ormas penyebar paham khilafah tidak boleh diloloskan; tolak tekanan pimpinan dan laporkan."},
{"id":"TKP-4416", "q":"Sebagai perawat, keluarga pasien meminta Anda tidak merawat pasien beda keyakinan karena alasan intoleran mereka. Sikap Anda?", "opts":[{"t":"Menolak permintaan diskriminatif dan tetap merawat sesuai sumpah profesi","s":5},{"t":"Melaporkan permintaan itu ke kepala ruangan","s":4},{"t":"Meminta perawat lain menggantikan","s":3},{"t":"Mengurangi intensitas perawatan","s":2},{"t":"Menuruti permintaan keluarga","s":1}], "ex":"Sumpah profesi kesehatan tidak mengenal diskriminasi keyakinan; tolak permintaan intoleran keluarga pasien."},
{"id":"TKP-4417", "q":"Dalam seleksi beasiswa daerah, kuota diam-diam dikhususkan untuk kelompok tertentu atas desakan tokoh intoleran. Anda panitia seleksi. Sikap Anda?", "opts":[{"t":"Menolak praktik itu dan melaporkannya ke pemberi beasiswa","s":5},{"t":"Memperjuangkan seleksi terbuka berbasis prestasi","s":4},{"t":"Mengundurkan diri dari panitia","s":3},{"t":"Mengikuti arahan karena sudah keputusan","s":2},{"t":"Ikut mengatur kuota diskriminatif itu","s":1}], "ex":"Beasiswa daerah adalah hak semua warga berprestasi; kuota diskriminatif desakan intoleran harus ditolak dan dilaporkan."},
{"id":"TKP-4418", "q":"Anda sopir ambulans dan diminta rekan menunda keberangkatan menjemput pasien dari kampung yang dibenci kelompok intoleran. Sikap Anda?", "opts":[{"t":"Menolak dan segera berangkat menjemput pasien","s":5},{"t":"Melaporkan permintaan itu ke atasan","s":4},{"t":"Berangkat tanpa menegur rekan","s":3},{"t":"Menunda sebentar agar tidak ribut","s":2},{"t":"Menuruti permintaan rekan","s":1}], "ex":"Nyawa pasien tidak boleh dikorbankan untuk sentimen intoleran; tolak dan segera berangkat."},
{"id":"TKP-4419", "q":"Sebagai petugas lapas, Anda mengetahui narapidana terorisme menyebarkan doktrin radikal ke napi lain. Sikap Anda?", "opts":[{"t":"Melaporkan ke kepala lapas dan Densus untuk pembinaan khusus","s":5},{"t":"Memisahkan napi tersebut dari napi lain","s":4},{"t":"Memperingatkannya agar berhenti","s":3},{"t":"Membiarkan karena di dalam lapas","s":2},{"t":"Ikut menyimak doktrinnya","s":1}], "ex":"Penyebaran doktrin radikal di lapas harus dilaporkan ke Densus; napi terorisme perlu pembinaan dan isolasi khusus."},
{"id":"TKP-4420", "q":"Warga meminta surat keterangan domisili dipersulit staf kelurahan karena ia pendatang dari daerah yang distigma kelompok intoleran. Anda lurahnya. Sikap Anda?", "opts":[{"t":"Memerintahkan pelayanan normal dan membina staf yang diskriminatif","s":5},{"t":"Menegur staf dan memastikan surat diterbitkan","s":4},{"t":"Menerbitkan sendiri tanpa menegur staf","s":3},{"t":"Membiarkan staf bekerja menurut caranya","s":2},{"t":"Mendukung staf karena memahami sentimennya","s":1}], "ex":"Diskriminasi layanan domisili atas stigma intoleran melanggar asas pelayanan publik; bina staf dan normalkan layanan."},
{"id":"TKP-4421", "q":"Anda juri lomba dan diminta panitia memenangkan peserta dari kelompok tertentu karena tekanan massa intoleran. Sikap Anda?", "opts":[{"t":"Menolak dan menilai objektif, melaporkan tekanan ke penyelenggara","s":5},{"t":"Tetap menilai objektif sesuai kriteria","s":4},{"t":"Mengundurkan diri sebagai juri","s":3},{"t":"Memenangkan peserta yang diminta","s":2},{"t":"Mendukung tekanan massa","s":1}], "ex":"Tekanan massa intoleran tidak boleh mengatur hasil lomba; nilai objektif dan laporkan tekanannya."},
{"id":"TKP-4422", "q":"Sebagai petugas bea cukai, Anda menemukan kiriman buku-buku doktrin teror dan khilafah dalam jumlah besar. Sikap Anda?", "opts":[{"t":"Menahan kiriman dan melaporkannya ke pihak berwajib","s":5},{"t":"Menyita kiriman sesuai prosedur kepabeanan","s":4},{"t":"Melaporkan ke atasan dan menunggu perintah","s":3},{"t":"Meloloskan karena hanya buku","s":2},{"t":"Meloloskan dengan imbalan","s":1}], "ex":"Kiriman massal doktrin teror adalah penyelundupan ideologi; tahan dan laporkan ke berwajib."},
{"id":"TKP-4423", "q":"Kepala desa Anda melarang warga mengadakan ibadah dengan alasan menjaga ketertiban, padahal karena desakan kelompok intoleran. Anda perangkat desa. Sikap Anda?", "opts":[{"t":"Menolak larangan diskriminatif dan melaporkannya ke camat","s":5},{"t":"Mengingatkan kepala desa tentang kebebasan beribadah yang dijamin konstitusi","s":4},{"t":"Diam karena ia atasan","s":3},{"t":"Mendukung larangan demi ketertiban","s":2},{"t":"Ikut membubarkan kegiatan ibadah","s":1}], "ex":"Larangan ibadah atas desakan intoleran melanggar konstitusi; ingatkan kepala desa dan laporkan ke camat."},
{"id":"TKP-4424", "q":"Anda petugas sensus dan responden menolak didata karena hasutan kelompok ekstrem bahwa sensus adalah pendataan musuh. Sikap Anda?", "opts":[{"t":"Menjelaskan manfaat sensus dengan sabar dan melaporkan hasutan itu","s":5},{"t":"Mengedukasi responden tentang pentingnya data kependudukan","s":4},{"t":"Melewati responden tersebut","s":3},{"t":"Memaksa dengan ancaman denda","s":2},{"t":"Ikut menyebarkan hasutannya","s":1}], "ex":"Hasutan ekstrem anti-sensus merugikan pembangunan data; edukasi warga dan laporkan penghasutnya."},
{"id":"TKP-4425", "q":"Sebagai pustakawan sekolah, komite menekan Anda menarik buku-buku toleransi karena dianggap menyimpang oleh kelompok intoleran. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tekanan itu ke kepala sekolah","s":5},{"t":"Mempertahankan buku-buku toleransi di rak","s":4},{"t":"Menyembunyikan buku tanpa menarik resmi","s":3},{"t":"Menarik buku agar tidak ribut","s":2},{"t":"Mendukung penarikan buku","s":1}], "ex":"Buku toleransi adalah benteng moderasi di sekolah; tolak tekanan intoleran dan laporkan ke kepala sekolah."},
{"id":"TKP-4426", "q":"Di voice chat gim daring, seorang pemain mengajak anggota klan bergabung ke grup latihan fisik yang ternyata kaderisasi kelompok ekstrem. Anda anggota klan. Sikap Anda?", "opts":[{"t":"Menolak, keluar dari klan, dan melaporkan ke pengembang gim serta pihak berwajib","s":5},{"t":"Menolak dan memperingatkan anggota klan lain","s":4},{"t":"Keluar dari klan tanpa melapor","s":3},{"t":"Tetap di klan tetapi tidak ikut latihan","s":2},{"t":"Ikut latihan fisiknya karena penasaran","s":1}], "ex":"Kaderisasi berkedok latihan fisik komunitas gim harus ditinggalkan dan dilaporkan ke pengembang serta berwajib."},
{"id":"TKP-4427", "q":"Turnamen gim yang Anda ikuti disponsori komunitas yang menyisipkan orasi penegakan khilafah di sela pertandingan. Sikap Anda sebagai peserta?", "opts":[{"t":"Mundur dari turnamen dan melaporkan sponsor itu","s":5},{"t":"Tidak ikut orasi dan memprotes ke panitia","s":4},{"t":"Fokus bertanding tanpa memedulikan orasi","s":3},{"t":"Mendengarkan orasi karena tidak ada pilihan","s":2},{"t":"Ikut berorasi mendukung khilafah","s":1}], "ex":"Turnamen gim berkedok orasi khilafah harus ditinggalkan; laporkan sponsor dan panitianya."},
{"id":"TKP-4428", "q":"Teman mabar Anda mengirim tautan unduhan mod gim yang ternyata berisi doktrin teror dan ajakan bergabung jaringan. Sikap Anda?", "opts":[{"t":"Tidak mengunduh dan melaporkan tautan itu ke pihak berwajib","s":5},{"t":"Menghapus tautan dan memperingatkan teman","s":4},{"t":"Mengabaikan tautannya","s":3},{"t":"Mengunduh karena penasaran isinya","s":2},{"t":"Mengunduh dan menyebarkan ke pemain lain","s":1}], "ex":"Mod gim berisi doktrin teror adalah umpan rekrutmen; jangan unduh dan laporkan tautannya."},
{"id":"TKP-4429", "q":"Di forum gim, seseorang membagikan panduan membuat senjata rakitan dengan dalih konten roleplay perjuangan khilafah. Anda moderator forum. Sikap Anda?", "opts":[{"t":"Menghapus konten, memblokir akun, dan melaporkannya ke pihak berwajib","s":5},{"t":"Menghapus konten berbahaya dan memperingatkan pembuatnya","s":4},{"t":"Menghapus tanpa melapor","s":3},{"t":"Membiarkan karena dianggap fiksi","s":2},{"t":"Menyimpan panduannya","s":1}], "ex":"Panduan senjata berkedok roleplay khilafah adalah konten teror; hapus, blokir, dan laporkan ke berwajib."},
{"id":"TKP-4430", "q":"Anak Anda kecanduan gim yang komunitasnya mengajarkan kebencian intoleran dan memuliakan pelaku teror. Sikap Anda sebagai orang tua?", "opts":[{"t":"Melaporkan komunitas itu, membatasi akses gim, dan membina anak","s":5},{"t":"Melarang anak bermain gim itu dan menjelaskan bahayanya","s":4},{"t":"Mengawasi tanpa melarang","s":3},{"t":"Membiarkan karena hanya permainan","s":2},{"t":"Ikut bermain bersamanya","s":1}], "ex":"Komunitas gim penyebar kebencian intoleran meracuni anak; batasi aksesnya, bina anak, laporkan komunitasnya."},
{"id":"TKP-4431", "q":"Streamer gim favorit Anda terang-terangan menggalang dana untuk kelompok ekstrem di sela siarannya. Sikap Anda sebagai penonton?", "opts":[{"t":"Berhenti menonton dan melaporkan siarannya ke platform serta berwajib","s":5},{"t":"Berhenti menonton dan melaporkan ke platform","s":4},{"t":"Berhenti menonton diam-diam","s":3},{"t":"Tetap menonton karena permainannya seru","s":2},{"t":"Ikut berdonasi karena mengidolakannya","s":1}], "ex":"Streamer penggalang dana kelompok ekstrem harus ditinggalkan dan dilaporkan ke platform serta berwajib."},
{"id":"TKP-4432", "q":"Grup chat tim e-sport Anda disusupi perekrut yang menawarkan beasiswa gaming dengan syarat mengikuti pembinaan ideologi khilafah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan perekrut itu ke manajemen tim serta berwajib","s":5},{"t":"Menolak dan memperingatkan rekan satu tim","s":4},{"t":"Menolak tawaran tanpa melapor","s":3},{"t":"Mempertimbangkan karena beasiswanya besar","s":2},{"t":"Menerima beasiswa dan ikut pembinaannya","s":1}], "ex":"Beasiswa gaming bersyarat pembinaan khilafah adalah umpan rekrutmen; tolak dan laporkan perekrutnya."},
{"id":"TKP-4433", "q":"Dalam gim, avatar Anda diajak bergabung ke guild bernama simbol perjuangan kelompok teror dan wajib mengikuti ritual sumpahnya. Sikap Anda?", "opts":[{"t":"Menolak, keluar dari guild, dan melaporkan ke pengembang gim","s":5},{"t":"Menolak dan memblokir perekrutnya","s":4},{"t":"Mengabaikan ajakannya","s":3},{"t":"Bergabung sekadar untuk misi gimnya","s":2},{"t":"Bergabung dan mengikuti ritual sumpahnya","s":1}], "ex":"Guild gim bersimbol kelompok teror dengan ritual sumpah adalah rekrutmen terselubung; laporkan ke pengembang."},
{"id":"TKP-4434", "q":"Teman Anda kecanduan gim lalu direkrut menjadi kurir dana jaringan radikal lewat misi dalam gim. Ia meminta saran Anda. Sikap Anda?", "opts":[{"t":"Menasihatinya berhenti total dan melaporkannya ke pihak berwajib","s":5},{"t":"Mendesaknya berhenti menjadi kurir dan keluar dari jaringan","s":4},{"t":"Menasihati agar hati-hati tanpa melapor","s":3},{"t":"Membiarkan karena itu pilihannya","s":2},{"t":"Ikut menjadi kurir karena imbalannya besar","s":1}], "ex":"Kurir dana jaringan radikal berkedok misi gim adalah tindak pidana; desak berhenti dan laporkan ke berwajib."},
{"id":"TKP-4435", "q":"Sebuah kafe gaming tempat Anda biasa bermain ternyata menjadi markas perekrutan kelompok ekstrem berkedok komunitas. Sikap Anda?", "opts":[{"t":"Berhenti datang dan melaporkan kafe itu ke pihak berwajib","s":5},{"t":"Berhenti datang dan memperingatkan teman-teman","s":4},{"t":"Pindah kafe gaming lain tanpa melapor","s":3},{"t":"Tetap datang karena tempatnya nyaman","s":2},{"t":"Ikut bergabung dengan komunitasnya","s":1}], "ex":"Kafe gaming berkedok markas perekrutan ekstrem harus ditinggalkan dan dilaporkan ke berwajib."},
{"id":"TKP-4436", "q":"Di kolom komentar video gim, seseorang menyebarkan nomor kontak perekrutan jaringan khilafah. Anda melihatnya. Tindakan Anda?", "opts":[{"t":"Melaporkan komentar itu ke platform dan pihak berwajib","s":5},{"t":"Melaporkan komentar ke platform","s":4},{"t":"Mengabaikannya","s":3},{"t":"Menyimpan nomornya untuk jaga-jaga","s":2},{"t":"Menghubungi nomor itu karena penasaran","s":1}], "ex":"Nomor perekrutan jaringan khilafah di kolom komentar harus dilaporkan ke platform dan berwajib."},
{"id":"TKP-4437", "q":"Adik Anda diminta kakak kelasnya membuat konten video game yang disisipi propaganda intoleran dengan imbalan skin premium. Sikap Anda sebagai kakak?", "opts":[{"t":"Melarang, melaporkan kakak kelas itu ke sekolah, dan mengedukasi adik","s":5},{"t":"Melarang adik dan menjelaskan bahaya propaganda","s":4},{"t":"Menasihati agar tidak usah ikut","s":3},{"t":"Membiarkan karena imbalannya menarik","s":2},{"t":"Membantu adik membuat kontennya","s":1}], "ex":"Imbalan skin untuk konten propaganda intoleran mengeksploitasi anak; larang, edukasi adik, laporkan ke sekolah."},
{"id":"TKP-4438", "q":"Sebuah gim populer merilis event berhadiah yang mensyaratkan pemain menyebarkan tagar dukungan khilafah. Anda pemain aktif. Sikap Anda?", "opts":[{"t":"Tidak ikut event dan melaporkan ke pengembang serta berwajib","s":5},{"t":"Tidak ikut dan memprotes di forum pemain","s":4},{"t":"Melewatkan event tersebut","s":3},{"t":"Ikut event demi hadiahnya","s":2},{"t":"Ikut dan menyebarkan tagarnya massal","s":1}], "ex":"Event gim bersyarat tagar khilafah adalah kampanye terselubung; jangan ikuti dan laporkan ke pengembang."},
{"id":"TKP-4439", "q":"Teman satu kos Anda begadang bermain gim sambil mengikuti ceramah ekstrem dari streamer dan mulai membenci pemerintah. Sikap Anda?", "opts":[{"t":"Menasihati dengan tegas dan melaporkannya bila menunjukkan gejala radikalisasi","s":5},{"t":"Mengajaknya diskusi sehat dan menjauhkan dari streamer ekstrem","s":4},{"t":"Membiarkan karena itu pilihannya","s":3},{"t":"Ikut mendengarkan streamernya","s":2},{"t":"Ikut membenci pemerintah bersamanya","s":1}], "ex":"Gejala radikalisasi pada teman sekamar harus dicegah dengan nasihat dan ajakan diskusi sehat; laporkan bila memburuk."},
{"id":"TKP-4440", "q":"Anda ditawari menjadi admin server gim privat yang dananya dari donatur jaringan teror. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tawaran itu ke pihak berwajib","s":5},{"t":"Menolak dengan tegas","s":4},{"t":"Mengabaikan tawaran","s":3},{"t":"Mempertimbangkan karena gajinya besar","s":2},{"t":"Menerima tawaran admin tersebut","s":1}], "ex":"Server gim berdana jaringan teror adalah fasad pendanaan; tolak dan laporkan ke berwajib."},
{"id":"TKP-4441", "q":"Dalam turnamen antar sekolah, suporter lawan meneriakkan yel-yel intoleran dan provokasi ekstrem. Anda peserta turnamen. Sikap Anda?", "opts":[{"t":"Tidak terprovokasi dan melaporkan ke panitia serta keamanan","s":5},{"t":"Tetap fokus bertanding dan mengabaikan provokasi","s":4},{"t":"Membalas dengan yel-yel balasan","s":3},{"t":"Ikut memanas dan berdebat","s":2},{"t":"Ikut meneriakkan yel-yel intoleran","s":1}], "ex":"Provokasi intoleran suporter tidak boleh dibalas; fokus bertanding dan laporkan ke panitia."},
{"id":"TKP-4442", "q":"Aplikasi obrolan khusus gamer yang Anda pakai dipakai koordinasi aksi penyerangan oleh kelompok ekstrem. Anda mengetahuinya. Tindakan Anda?", "opts":[{"t":"Melaporkan ke pengembang aplikasi dan pihak kepolisian","s":5},{"t":"Keluar dari grup koordinasi dan menyimpan bukti","s":4},{"t":"Keluar diam-diam","s":3},{"t":"Tetap di grup untuk memantau","s":2},{"t":"Ikut dalam koordinasi aksinya","s":1}], "ex":"Koordinasi aksi kekerasan di aplikasi gamer harus dilaporkan ke pengembang dan polisi dengan bukti."},
{"id":"TKP-4443", "q":"Seorang pro player mengajak fansnya memboikot produk dengan dalih perusahaan itu musuh khilafah menurut paham ekstremnya. Anda fansnya. Sikap Anda?", "opts":[{"t":"Tidak ikut boikot dan melaporkan hasutannya","s":5},{"t":"Mengabaikan ajakan boikotnya","s":4},{"t":"Berhenti menjadi fans diam-diam","s":3},{"t":"Ikut boikot agar dianggap fans sejati","s":2},{"t":"Ikut mengkampanyekan boikotnya","s":1}], "ex":"Ajakan boikot berbasis paham ekstrem oleh figur publik harus diabaikan dan dilaporkan."},
{"id":"TKP-4444", "q":"Teman Anda menjual akun gim mahalnya dan hasilnya disumbangkan ke jaringan pengusung teror. Ia bangga bercerita. Sikap Anda?", "opts":[{"t":"Menasihati bahaya perbuatannya dan melaporkannya","s":5},{"t":"Menasihatinya agar berhenti mendanai jaringan teror","s":4},{"t":"Diam karena tidak ingin bertengkar","s":3},{"t":"Memuji kepeduliannya","s":2},{"t":"Ikut menjual akun untuk disumbangkan","s":1}], "ex":"Hasil penjualan akun untuk jaringan teror adalah pendanaan terorisme; nasihati dan laporkan."},
{"id":"TKP-4445", "q":"Di warnet langganan Anda, operator memutar video rekrutmen kelompok radikal di layar utama setiap malam. Sikap Anda sebagai pelanggan?", "opts":[{"t":"Berhenti berlangganan dan melaporkan warnet itu ke pihak berwajib","s":5},{"t":"Memprotes operator agar menghentikan pemutaran","s":4},{"t":"Pindah warnet tanpa protes","s":3},{"t":"Tetap bermain sambil mengabaikan videonya","s":2},{"t":"Menonton videonya dengan saksama","s":1}], "ex":"Warnet pemutar video rekrutmen radikal adalah sarang radikalisasi; tinggalkan dan laporkan ke berwajib."},
{"id":"TKP-4446", "q":"Anda menerima undangan beta test gim baru, tetapi syaratnya mengisi formulir afiliasi ideologi khilafah. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan gim itu ke pihak berwajib","s":5},{"t":"Menolak undangan dengan tegas","s":4},{"t":"Mengabaikan undangan","s":3},{"t":"Mengisi seadanya demi mencoba gimnya","s":2},{"t":"Mengisi lengkap dan bergabung","s":1}], "ex":"Beta test bersyarat afiliasi khilafah adalah rekrutmen berkedok gim; tolak dan laporkan."},
{"id":"TKP-4447", "q":"Komunitas cosplay gim Anda disusupi anggota yang menyebarkan simbol dan doktrin kelompok ekstrem lewat kostumnya. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengurus komunitas dan pihak berwajib","s":5},{"t":"Meminta pengurus melarang atribut tersebut","s":4},{"t":"Menjauh dari anggota itu","s":3},{"t":"Membiarkan karena kreativitas","s":2},{"t":"Ikut memakai atribut serupa","s":1}], "ex":"Simbol kelompok ekstrem berkedok cosplay tetap propaganda; laporkan ke pengurus dan berwajib."},
{"id":"TKP-4448", "q":"Teman mabar Anda mengaku direkrut menjadi penerjemah propaganda teror berbahasa asing dengan bayaran dolar. Ia meminta pendapat Anda. Sikap Anda?", "opts":[{"t":"Menasihatinya berhenti dan melaporkan ke pihak berwajib","s":5},{"t":"Mendesaknya keluar sebelum terlambat","s":4},{"t":"Menasihati agar berhati-hati","s":3},{"t":"Mengagumi karena bayarannya dolar","s":2},{"t":"Meminta dikenalkan agar ikut","s":1}], "ex":"Penerjemah propaganda teror adalah bagian jaringan; desak berhenti dan laporkan ke berwajib."},
{"id":"TKP-4449", "q":"Sebuah liga gim amatir mewajibkan peserta menandatangani pakta setia pada ideologi khilafah panitianya. Anda ingin ikut liga. Sikap Anda?", "opts":[{"t":"Tidak ikut dan melaporkan panitia ke pihak berwajib","s":5},{"t":"Memprotes syarat pakta itu ke panitia","s":4},{"t":"Mundur diam-diam","s":3},{"t":"Menandatangani agar bisa bertanding","s":2},{"t":"Menandatangani dengan bangga","s":1}], "ex":"Pakta setia khilafah sebagai syarat liga adalah baiat terselubung; jangan ikuti dan laporkan panitianya."},
{"id":"TKP-4450", "q":"Anak tetangga Anda menghilang dan belakangan diketahui direkrut lewat gim daring oleh jaringan ekstrem. Orang tuanya meminta bantuan Anda. Sikap Anda?", "opts":[{"t":"Membantu melapor ke polisi dan memberikan semua informasi tentang gimnya","s":5},{"t":"Mendampingi orang tua melapor ke pihak berwajib","s":4},{"t":"Menyarankan melapor tanpa ikut terlibat","s":3},{"t":"Menganggap itu urusan keluarga mereka","s":2},{"t":"Menyalahkan orang tuanya yang lalai","s":1}], "ex":"Anak hilang karena rekrutmen gim oleh jaringan ekstrem adalah keadaan darurat; bantu keluarga melapor ke polisi."},
{"id":"TKP-4451", "q":"Anda ditawari pekerjaan sebagai penulis naskah konten yang isinya propaganda khilafah untuk disebar jaringan buzzer lintas negara. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tawaran itu ke pihak berwajib","s":5},{"t":"Menolak dengan tegas","s":4},{"t":"Mengabaikan tawaran","s":3},{"t":"Mempertimbangkan karena gajinya tinggi","s":2},{"t":"Menerima pekerjaan itu","s":1}], "ex":"Penulis propaganda khilafah untuk buzzer transnasional adalah bagian mesin radikalisasi; tolak dan laporkan."},
{"id":"TKP-4452", "q":"Tagar dukungan kelompok ekstrem menjadi trending topic dan Anda tahu itu hasil operasi buzzer bayaran. Sikap Anda sebagai warganet?", "opts":[{"t":"Tidak ikut memakai tagar dan melaporkan indikasi operasi buzzer","s":5},{"t":"Mengedukasi pengikut agar tidak ikut memakai tagar itu","s":4},{"t":"Mengabaikan trending tersebut","s":3},{"t":"Memakai tagar karena sedang viral","s":2},{"t":"Ikut menyebarkan tagarnya","s":1}], "ex":"Trending hasil buzzer kelompok ekstrem harus dilawan dengan tidak ikut serta dan melaporkannya."},
{"id":"TKP-4453", "q":"Teman Anda bangga menjadi buzzer yang dibayar untuk menyebarkan ujaran intoleran dan membela aksi teror. Sikap Anda?", "opts":[{"t":"Menasihatinya berhenti dan melaporkan jaringannya ke berwajib","s":5},{"t":"Mendesaknya keluar dari pekerjaan buzzer itu","s":4},{"t":"Menjauhinya tanpa menasihati","s":3},{"t":"Membiarkan karena itu pekerjaannya","s":2},{"t":"Meminta dikenalkan ke koordinatornya","s":1}], "ex":"Buzzer penyebar intoleransi dan pembela teror merusak ruang digital; desak berhenti dan laporkan jaringannya."},
{"id":"TKP-4454", "q":"Sebuah akun anonim besar menyebarkan video deepfake pejabat yang memicu kebencian ekstrem terhadap pemerintah. Anda melihat videonya viral. Sikap Anda?", "opts":[{"t":"Melaporkan video deepfake itu dan menyebarkan klarifikasi","s":5},{"t":"Melaporkan ke platform sebagai konten menyesatkan","s":4},{"t":"Tidak menyebarkan tanpa melapor","s":3},{"t":"Menyebarkan karena videonya meyakinkan","s":2},{"t":"Ikut menghasut di kolom komentar","s":1}], "ex":"Deepfake pemicu kebencian ekstrem harus dilaporkan dan diklarifikasi agar tidak memicu kerusuhan."},
{"id":"TKP-4455", "q":"Anda menemukan pola ratusan akun baru yang serentak menyebarkan narasi khilafah dengan bahasa yang sama. Tindakan Anda?", "opts":[{"t":"Melaporkan temuan pola itu ke pihak berwajib sebagai operasi terkoordinasi","s":5},{"t":"Melaporkan akun-akun itu ke platform","s":4},{"t":"Mengabaikan karena bukan urusan Anda","s":3},{"t":"Mengikuti salah satu akun karena penasaran","s":2},{"t":"Ikut menyebarkan narasinya","s":1}], "ex":"Pola akun serentak penyebar narasi khilafah adalah operasi buzzer; laporkan ke berwajib sebagai temuan terkoordinasi."},
{"id":"TKP-4456", "q":"Seorang kerabat di luar negeri mengirimi Anda materi propaganda kelompok ekstrem untuk disebarkan di Indonesia. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan materi itu ke pihak berwajib","s":5},{"t":"Menolak dan memintanya berhenti mengirim","s":4},{"t":"Menghapus materi tanpa melapor","s":3},{"t":"Menyimpan untuk dibaca sendiri","s":2},{"t":"Menyebarkannya ke kontak Indonesia","s":1}], "ex":"Propaganda transnasional kelompok ekstrem yang masuk lewat kerabat harus ditolak dan dilaporkan ke berwajib."},
{"id":"TKP-4457", "q":"Di grup diaspora Indonesia, admin menyebarkan seruan penggalangan dana untuk perjuangan khilafah di tanah air. Anda anggota grup. Sikap Anda?", "opts":[{"t":"Melaporkan admin dan keluar dari grup","s":5},{"t":"Memprotes dan meminta admin menghentikan seruan","s":4},{"t":"Keluar diam-diam","s":3},{"t":"Tetap di grup sebagai penyimak","s":2},{"t":"Ikut berdonasi","s":1}], "ex":"Seruan dana khilafah di grup diaspora adalah pendanaan transnasional; protes, keluar, dan laporkan adminnya."},
{"id":"TKP-4458", "q":"Anda diminta menerjemahkan dokumen propaganda teror ke bahasa Indonesia dengan bayaran mahal oleh kontak luar negeri. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan kontak itu ke pihak berwajib","s":5},{"t":"Menolak dengan tegas","s":4},{"t":"Mengabaikan tawarannya","s":3},{"t":"Mempertimbangkan karena bayarannya mahal","s":2},{"t":"Menerima pekerjaan terjemahan itu","s":1}], "ex":"Menerjemahkan propaganda teror adalah kejahatan; tolak bayaran mahal itu dan laporkan kontaknya."},
{"id":"TKP-4459", "q":"Sebuah media asing menyiarkan wawancara yang memuliakan kelompok ekstrem Indonesia sebagai pejuang. Anda menontonnya. Sikap Anda?", "opts":[{"t":"Melaporkan konten itu dan menyebarkan sanggahan","s":5},{"t":"Tidak menyebarkan dan mengkritik narasinya","s":4},{"t":"Mengabaikannya","s":3},{"t":"Membagikan karena narasumbernya terkenal","s":2},{"t":"Mendukung narasi media itu","s":1}], "ex":"Pemuliaan kelompok ekstrem oleh media asing harus disanggah dan dilaporkan, bukan disebarkan."},
{"id":"TKP-4460", "q":"Teman Anda membuat puluhan akun palsu untuk mengamplifikasi ujaran intoleran menjelang pemilu. Sikap Anda?", "opts":[{"t":"Menasihatinya berhenti dan melaporkannya ke Bawaslu serta berwajib","s":5},{"t":"Mendesaknya menghapus akun-akun palsu itu","s":4},{"t":"Menjauhinya","s":3},{"t":"Membiarkan karena musim pemilu","s":2},{"t":"Meminta dibuatkan akun palsu juga","s":1}], "ex":"Akun palsu pengamplifikasi intoleransi merusak pemilu; desak dihapus dan laporkan ke Bawaslu."},
{"id":"TKP-4461", "q":"Anda menerima pesan berantai berisi hasutan ekstrem untuk menyerang tempat ibadah kelompok lain malam ini. Tindakan Anda?", "opts":[{"t":"Segera melaporkan pesan itu ke kepolisian","s":5},{"t":"Meneruskan peringatan ke ketua lingkungan dan aparat","s":4},{"t":"Menghapus pesan berantai itu","s":3},{"t":"Mengabaikan karena menganggap hoaks","s":2},{"t":"Meneruskan pesan itu ke grup lain","s":1}], "ex":"Hasutan penyerangan tempat ibadah adalah ancaman nyata; segera laporkan ke polisi, jangan disebar."},
{"id":"TKP-4462", "q":"Sebuah LSM asing menawarkan Anda proyek riset yang datanya dipakai untuk memetakan target perekrutan jaringan radikal. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tawaran mencurigakan itu","s":5},{"t":"Menolak tawaran dengan tegas","s":4},{"t":"Mengabaikan tawarannya","s":3},{"t":"Mempertimbangkan karena dananya besar","s":2},{"t":"Menerima proyek riset itu","s":1}], "ex":"Riset berkedok LSM untuk pemetaan target perekrutan radikal harus ditolak dan dilaporkan."},
{"id":"TKP-4463", "q":"Influencer luar negeri mengajak pengikut Indonesianya bergabung dalam kampanye global penegakan khilafah. Anda pengikutnya. Sikap Anda?", "opts":[{"t":"Berhenti mengikuti dan melaporkan kampanyenya","s":5},{"t":"Mengabaikan ajakan kampanyenya","s":4},{"t":"Berhenti mengikuti diam-diam","s":3},{"t":"Tetap mengikuti karena konten lainnya menarik","s":2},{"t":"Bergabung dalam kampanyenya","s":1}], "ex":"Kampanye global khilafah oleh influencer asing menarget WNI; jangan ikuti dan laporkan."},
{"id":"TKP-4464", "q":"Anda menemukan situs web berbahasa Indonesia yang menjadi pusat komando propaganda teror lintas negara. Tindakan Anda?", "opts":[{"t":"Melaporkan situs itu ke pihak berwajib dan kominfo","s":5},{"t":"Melaporkan ke kominfo untuk diblokir","s":4},{"t":"Menutup situsnya tanpa melapor","s":3},{"t":"Membaca isinya karena penasaran","s":2},{"t":"Membagikan tautannya","s":1}], "ex":"Situs pusat komando propaganda teror harus dilaporkan ke berwajib dan Kominfo agar diblokir."},
{"id":"TKP-4465", "q":"Rekan kerja Anda diam-diam menjadi penerjemah siaran propaganda kelompok ekstrem untuk audiens Indonesia. Anda mengetahuinya. Sikap Anda?", "opts":[{"t":"Melaporkan ke atasan dan pihak berwajib","s":5},{"t":"Mendesaknya berhenti sebelum terlambat","s":4},{"t":"Menjaga rahasianya","s":3},{"t":"Membiarkan karena di luar jam kerja","s":2},{"t":"Meminta dikenalkan ke jaringannya","s":1}], "ex":"Penerjemah propaganda kelompok ekstrem adalah bagian jaringan; laporkan ke atasan dan berwajib."},
{"id":"TKP-4466", "q":"Sebuah festival budaya internasional disusupi stan yang menyebarkan literatur khilafah dan intoleran. Anda pengunjung festival. Sikap Anda?", "opts":[{"t":"Melaporkan stan itu ke panitia dan pihak berwenang","s":5},{"t":"Memprotes ke panitia festival","s":4},{"t":"Menghindari stan tersebut","s":3},{"t":"Mampir karena penasaran","s":2},{"t":"Mengambil literaturnya untuk dibaca","s":1}], "ex":"Stan penyebar literatur khilafah di festival budaya harus dilaporkan ke panitia dan berwenang."},
{"id":"TKP-4467", "q":"Anda diminta menjadi pembicara bayaran di konferensi luar negeri yang ternyata forum konsolidasi jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan undangan itu ke pihak berwajib","s":5},{"t":"Menolak undangan dengan tegas","s":4},{"t":"Mengabaikan undangan","s":3},{"t":"Mempertimbangkan karena dibiayai penuh","s":2},{"t":"Menerima dan berangkat","s":1}], "ex":"Konferensi konsolidasi jaringan ekstrem berkedok forum internasional harus ditolak dan dilaporkan."},
{"id":"TKP-4468", "q":"Teman Anda memproduksi lagu dan film pendek yang memuliakan pelaku teror untuk disebar jaringan buzzer. Sikap Anda?", "opts":[{"t":"Menasihatinya berhenti dan melaporkan produksinya","s":5},{"t":"Mendesaknya menghentikan produksi","s":4},{"t":"Menjauhinya","s":3},{"t":"Menonton karyanya karena bagus","s":2},{"t":"Membantu menyebarkan karyanya","s":1}], "ex":"Karya seni pemulia pelaku teror adalah propaganda; desak berhenti dan laporkan produksinya."},
{"id":"TKP-4469", "q":"Sebuah aplikasi pesan instan asing menolak menghapus kanal propaganda teror Indonesia meski sudah dilaporkan. Sikap Anda sebagai pengguna?", "opts":[{"t":"Melaporkan ke Kominfo dan berhenti memakai aplikasi itu","s":5},{"t":"Melaporkan kanal itu berulang kali ke platform","s":4},{"t":"Memblokir kanal tersebut","s":3},{"t":"Tetap memakai aplikasi seperti biasa","s":2},{"t":"Bergabung ke kanal itu karena penasaran","s":1}], "ex":"Platform yang melindungi kanal propaganda teror harus dilaporkan ke Kominfo; lindungi diri dengan memblokir."},
{"id":"TKP-4470", "q":"Anda menemukan dokumen bocor berisi rencana serangan kelompok ekstrem yang disebar buzzer untuk menakuti publik. Tindakan Anda?", "opts":[{"t":"Segera menyerahkan dokumen itu ke pihak kepolisian","s":5},{"t":"Melaporkan ke aparat keamanan terdekat","s":4},{"t":"Menyimpan dokumen tanpa melapor","s":3},{"t":"Menyebarkan ke grup agar warga waspada","s":2},{"t":"Mengabaikan karena menganggap hoaks","s":1}], "ex":"Dokumen rencana serangan kelompok ekstrem adalah informasi krusial; serahkan segera ke polisi, jangan disebar."},
{"id":"TKP-4471", "q":"Seorang WNA mengajak komunitas Anda berkolaborasi menyebarkan ideologi khilafah dengan dalih pertukaran budaya. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan WNA itu ke pihak berwajib","s":5},{"t":"Menolak ajakan kolaborasi dengan tegas","s":4},{"t":"Mengabaikan ajakannya","s":3},{"t":"Mempertimbangkan karena dananya besar","s":2},{"t":"Menerima kolaborasi","s":1}], "ex":"Kolaborasi berkedok budaya untuk ideologi khilafah adalah infiltrasi; tolak dan laporkan WNA-nya."},
{"id":"TKP-4472", "q":"Akun-akun buzzer menyerang Anda secara pribadi karena Anda mengkritik paham khilafah di media sosial. Sikap Anda?", "opts":[{"t":"Melaporkan serangan itu dan tetap menyuarakan kritik secara santun","s":5},{"t":"Memblokir akun penyerang dan melaporkan","s":4},{"t":"Menghapus kritik Anda agar serangan berhenti","s":3},{"t":"Membalas dengan emosi","s":2},{"t":"Menarik kritik dan meminta maaf","s":1}], "ex":"Serangan buzzer tidak boleh membungkam kritik terhadap khilafah; laporkan dan tetap bersuara santun."},
{"id":"TKP-4473", "q":"Anda diundang menjadi juri lomba konten kreator yang sponsornya jaringan buzzer penyebar intoleransi. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan sponsor itu","s":5},{"t":"Menolak undangan juri dengan tegas","s":4},{"t":"Mengabaikan undangan","s":3},{"t":"Menerima karena hadiahnya besar","s":2},{"t":"Menerima dan mempromosikan sponsornya","s":1}], "ex":"Lomba bersponsor buzzer intoleransi memberi panggung pada kebencian; tolak jadi juri dan laporkan."},
{"id":"TKP-4474", "q":"Sebuah penerbit luar negeri menawarkan Anda menulis buku yang isinya pembenaran terorisme dengan royalti besar. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan tawaran itu ke pihak berwajib","s":5},{"t":"Menolak dengan tegas","s":4},{"t":"Mengabaikan tawarannya","s":3},{"t":"Mempertimbangkan karena royalti besar","s":2},{"t":"Menerima tawaran menulis itu","s":1}], "ex":"Tawaran menulis pembenaran terorisme adalah kejahatan; tolak royalti besar itu dan laporkan."},
{"id":"TKP-4475", "q":"Teman Anda direkrut menjadi admin grup lintas negara yang mengoordinasikan penyebaran hoaks ekstrem. Ia meminta Anda bergabung. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan grup itu ke pihak berwajib","s":5},{"t":"Menasihati teman agar keluar dari grup","s":4},{"t":"Menolak tanpa menasihati","s":3},{"t":"Bergabung sebagai penyimak","s":2},{"t":"Bergabung menjadi admin","s":1}], "ex":"Grup lintas negara penyebar hoaks ekstrem adalah operasi terkoordinasi; tolak dan laporkan ke berwajib."},
{"id":"TKP-4476", "q":"Mantan narapidana terorisme melamar kerja di instansi Anda setelah menjalani deradikalisasi dan dinyatakan bersih. Sikap Anda sebagai pewawancara?", "opts":[{"t":"Menilai objektif berbasis kompetensi dan berkoordinasi dengan pembinanya","s":5},{"t":"Memberi kesempatan dengan masa percobaan dan pendampingan","s":4},{"t":"Menolak dengan halus tanpa alasan jelas","s":3},{"t":"Menolak karena takut","s":2},{"t":"Menyebarkan identitasnya agar ditolak di mana-mana","s":1}], "ex":"Mantan napiter yang lolos deradikalisasi berhak reintegrasi; nilai objektif dan koordinasikan pembinaan lanjutan."},
{"id":"TKP-4477", "q":"Tetangga Anda yang mantan simpatisan kelompok ekstrem kini aktif di kegiatan karang taruna dan menunjukkan perubahan. Sikap Anda?", "opts":[{"t":"Mendukung reintegrasinya dan melibatkannya dalam kegiatan positif","s":5},{"t":"Menerima kehadirannya dengan wajar","s":4},{"t":"Mengawasinya diam-diam","s":3},{"t":"Menjauhinya karena masa lalunya","s":2},{"t":"Mengusirnya dari lingkungan","s":1}], "ex":"Reintegrasi mantan simpatisan ekstrem perlu dukungan lingkungan; libatkan dalam kegiatan positif, bukan dikucilkan."},
{"id":"TKP-4478", "q":"Anak buah Anda ketahuan masih menyimpan materi lama kelompok radikal meski mengaku sudah bertobat. Sikap Anda sebagai atasan?", "opts":[{"t":"Membinanya, memusnahkan materi, dan melaporkannya ke pembina deradikalisasi","s":5},{"t":"Menasihati serius dan memintanya menyerahkan materi itu","s":4},{"t":"Memberi peringatan lisan saja","s":3},{"t":"Membiarkan karena ia sudah bertobat","s":2},{"t":"Ikut menyimpan materinya","s":1}], "ex":"Materi lama kelompok radikal yang masih disimpan adalah risiko kambuh; bina, musnahkan, dan laporkan ke pembina."},
{"id":"TKP-4479", "q":"Sekolah anak Anda menolak menerima siswa pindahan yang orang tuanya mantan narapidana terorisme meski sudah bebas murni. Sikap Anda sebagai orang tua murid?", "opts":[{"t":"Mendukung penerimaan siswa itu dan mengedukasi komite tentang reintegrasi","s":5},{"t":"Tidak keberatan anak sekelas dengannya","s":4},{"t":"Diam tidak ikut campur","s":3},{"t":"Ikut menolak demi keamanan","s":2},{"t":"Menggalang penolakan orang tua lain","s":1}], "ex":"Anak mantan napiter berhak atas pendidikan; dukung penerimaannya dan edukasi komite tentang reintegrasi."},
{"id":"TKP-4480", "q":"Rekan kerja yang sedang dibina deradikalisasi kambuh menyebarkan paham intoleran di kantor. Sikap Anda?", "opts":[{"t":"Melaporkan kekambuhannya ke pembina dan pimpinan","s":5},{"t":"Menasihati dengan tegas agar kembali ke pembinaan","s":4},{"t":"Menjauhinya","s":3},{"t":"Membiarkan karena kasihan","s":2},{"t":"Ikut menyebarkan pahamnya","s":1}], "ex":"Kekambuhan peserta deradikalisasi harus segera dilaporkan ke pembina agar penanganannya tidak terlambat."},
{"id":"TKP-4481", "q":"Anda diminta menjadi mentor mantan simpatisan ekstrem dalam program reintegrasi di lingkungan kerja. Sikap Anda?", "opts":[{"t":"Menerima dengan tanggung jawab dan berkoordinasi dengan pembina","s":5},{"t":"Menerima dan membimbingnya dengan sabar","s":4},{"t":"Menolak dengan halus","s":3},{"t":"Menolak karena takut","s":2},{"t":"Menolak sambil menyebarkan identitasnya","s":1}], "ex":"Mentor reintegrasi adalah peran mulia dalam deradikalisasi; terima dengan koordinasi pembina yang tepat."},
{"id":"TKP-4482", "q":"Warga menolak pembangunan rumah mantan narapidana terorisme di lingkungannya meski ia sudah bebas dan dibina. Anda ketua RT. Sikap Anda?", "opts":[{"t":"Mengedukasi warga tentang reintegrasi dan memfasilitasi penerimaannya","s":5},{"t":"Memediasi dialog antara warga dan yang bersangkutan","s":4},{"t":"Membiarkan penolakan warga","s":3},{"t":"Ikut menolak demi menjaga suara warga","s":2},{"t":"Mengusirnya dari RT","s":1}], "ex":"Ketua RT wajib mengedukasi warga tentang reintegrasi mantan napiter yang sudah dibina, bukan ikut mengusir."},
{"id":"TKP-4483", "q":"Anak Anda berteman dengan anak mantan anggota kelompok ekstrem dan Anda khawatir tertular pahamnya. Sikap Anda?", "opts":[{"t":"Mengenal keluarganya, memastikan pembinaannya, dan tetap mengawasi wajar","s":5},{"t":"Mengawasi pertemanan mereka dengan bijak","s":4},{"t":"Melarang berteman tanpa penjelasan","s":3},{"t":"Melarang keras dan memusuhi keluarganya","s":2},{"t":"Melaporkan keluarga itu ke polisi tanpa bukti","s":1}], "ex":"Stigma pada anak mantan anggota ekstrem tidak adil; kenali keluarganya, pastikan pembinaan, awasi dengan wajar."},
{"id":"TKP-4484", "q":"Program deradikalisasi di lapas tempat Anda bertugas kekurangan anggaran dan terancam berhenti. Sikap Anda?", "opts":[{"t":"Mengusulkan solusi anggaran ke pimpinan karena program itu vital","s":5},{"t":"Mendukung kelanjutan program dengan sumber daya yang ada","s":4},{"t":"Diam mengikuti keputusan pimpinan","s":3},{"t":"Mendukung penghentian karena menghemat anggaran","s":2},{"t":"Mengusulkan program dihapus","s":1}], "ex":"Deradikalisasi adalah benteng pencegahan terorisme; perjuangkan kelanjutannya ke pimpinan."},
{"id":"TKP-4485", "q":"Mantan simpatisan radikal yang Anda bina berhasil menjadi penggerak antiradikalisme di komunitasnya. Sikap Anda?", "opts":[{"t":"Mendukung penuh dan menjadikannya contoh keberhasilan pembinaan","s":5},{"t":"Mengapresiasi perubahan dan kiprahnya","s":4},{"t":"Biasa saja","s":3},{"t":"Curiga itu hanya pencitraan","s":2},{"t":"Menyebarkan masa lalunya untuk menjatuhkan","s":1}], "ex":"Keberhasilan pembinaan mantan simpatisan radikal patut didukung dan dijadikan contoh, bukan dicurigai."},
{"id":"TKP-4486", "q":"Istri mantan narapidana terorisme melamar sebagai tenaga honorer di instansi Anda. Sikap Anda sebagai panitia seleksi?", "opts":[{"t":"Menilai objektif berbasis kompetensi tanpa diskriminasi status","s":5},{"t":"Memberi kesempatan yang sama seperti pelamar lain","s":4},{"t":"Menggugurkan dengan halus","s":3},{"t":"Menolak karena status suaminya","s":2},{"t":"Menyebarkan statusnya agar ditolak","s":1}], "ex":"Keluarga mantan napiter tidak boleh didiskriminasi; seleksi harus objektif berbasis kompetensi."},
{"id":"TKP-4487", "q":"Anda menemukan mantan rekan kelompok ekstrem lama menghubungi Anda untuk kembali aktif. Anda sudah bertobat. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan kontak itu ke pihak berwajib","s":5},{"t":"Menolak tegas dan memblokir kontaknya","s":4},{"t":"Mengabaikan pesannya","s":3},{"t":"Melayaninya sekadar nostalgia","s":2},{"t":"Kembali aktif bersamanya","s":1}], "ex":"Ajakan kembali ke jaringan lama setelah bertobat harus ditolak tegas dan dilaporkan ke berwajib."},
{"id":"TKP-4488", "q":"Kegiatan pembinaan wawasan kebangsaan untuk mantan simpatisan radikal di kantor Anda diejek rekan sebagai pencitraan. Sikap Anda?", "opts":[{"t":"Membela program itu dan menjelaskan pentingnya deradikalisasi","s":5},{"t":"Tetap mendukung program meski diejek","s":4},{"t":"Diam tidak membela","s":3},{"t":"Ikut mengejek agar diterima pergaulan","s":2},{"t":"Mengusulkan program dibubarkan","s":1}], "ex":"Pembinaan wawasan kebangsaan bagi mantan simpatisan adalah investasi keamanan; bela dari ejekan sinis."},
{"id":"TKP-4489", "q":"Anak mantan anggota kelompok teror berprestasi di sekolah dan akan mewakili daerah di lomba nasional, tetapi panitia ragu memberangkatkan. Sikap Anda sebagai guru?", "opts":[{"t":"Memperjuangkan keberangkatannya berbasis prestasi","s":5},{"t":"Mendukung dan mendampinginya","s":4},{"t":"Netral mengikuti keputusan panitia","s":3},{"t":"Setuju dengan keraguan panitia","s":2},{"t":"Mendukung pembatalan keberangkatan","s":1}], "ex":"Prestasi anak tidak boleh dikubur karena masa lalu orang tuanya; perjuangkan haknya berbasis merit."},
{"id":"TKP-4490", "q":"Anda mengetahui mantan narapidana terorisme yang sudah dibina justru merekrut kembali tetangganya. Sikap Anda?", "opts":[{"t":"Segera melaporkan ke pihak berwajib dan pembinanya","s":5},{"t":"Melaporkan ke ketua lingkungan dan polisi","s":4},{"t":"Memperingatkan tetangga yang direkrut","s":3},{"t":"Diam karena takut","s":2},{"t":"Ikut direkrut karena diajak","s":1}], "ex":"Mantan napiter yang kembali merekrut adalah kegagalan pembinaan yang berbahaya; segera laporkan ke berwajib."},
{"id":"TKP-4491", "q":"Lembaga Anda akan mempekerjakan konsultan deradikalisasi, tetapi ada penolakan karena dianggap menghamburkan anggaran. Sikap Anda?", "opts":[{"t":"Membela kebutuhan konsultan dengan data ancaman radikalisme","s":5},{"t":"Mendukung pengadaan konsultan","s":4},{"t":"Netral","s":3},{"t":"Ikut menolak demi penghematan","s":2},{"t":"Mengusulkan anggaran dialihkan","s":1}], "ex":"Deradikalisasi butuh ahli; bela pengadaan konsultan dengan data ancaman yang nyata."},
{"id":"TKP-4492", "q":"Mantan simpatisan ekstrem yang bertobat ingin bersaksi di sekolah-sekolah tentang bahaya radikalisme. Sikap Anda sebagai kepala sekolah?", "opts":[{"t":"Menerima dan memfasilitasi kesaksiannya sebagai edukasi","s":5},{"t":"Menerima dengan pendampingan guru","s":4},{"t":"Menolak dengan halus","s":3},{"t":"Menolak karena takut citra sekolah","s":2},{"t":"Melarang dan menyebarkan masa lalunya","s":1}], "ex":"Kesaksian mantan simpatisan adalah edukasi antiradikalisme yang kuat; fasilitasi dengan pendampingan."},
{"id":"TKP-4493", "q":"Keluarga Anda malu karena saudara menjadi mantan narapidana terorisme dan ingin memutus hubungan. Sikap Anda?", "opts":[{"t":"Menasihati keluarga mendukung pembinaannya, bukan memutus hubungan","s":5},{"t":"Tetap menjalin silaturahmi dan membimbingnya","s":4},{"t":"Diam mengikuti keputusan keluarga","s":3},{"t":"Ikut memutus hubungan","s":2},{"t":"Mengusirnya dari keluarga besar","s":1}], "ex":"Dukungan keluarga menentukan keberhasilan deradikalisasi; nasihati keluarga untuk merangkul, bukan mengucilkan."},
{"id":"TKP-4494", "q":"Anda diminta menyusun modul pembinaan bagi pegawai terpapar paham intoleran. Sikap Anda?", "opts":[{"t":"Menyusun modul berbasis wawasan kebangsaan dan moderasi dengan serius","s":5},{"t":"Menyusun modul sebaik mungkin","s":4},{"t":"Menolak dengan alasan sibuk","s":3},{"t":"Menyusun asal-asalan","s":2},{"t":"Menolak karena menganggap percuma","s":1}], "ex":"Modul pembinaan pegawai terpapar intoleransi adalah tugas strategis; susun serius berbasis wawasan kebangsaan."},
{"id":"TKP-4495", "q":"Mantan anggota kelompok khilafah membuka usaha kuliner dan meminta Anda mempromosikannya. Sikap Anda?", "opts":[{"t":"Membantu promosi sebagai bentuk dukungan reintegrasi ekonomi","s":5},{"t":"Membeli dan mempromosikan usahanya","s":4},{"t":"Membeli sesekali tanpa promosi","s":3},{"t":"Menghindari usahanya","s":2},{"t":"Memboikot dan menyebarkan masa lalunya","s":1}], "ex":"Kemandirian ekonomi mantan anggota adalah kunci reintegrasi; dukung usahanya, jangan boikot."},
{"id":"TKP-4496", "q":"Tetangga melaporkan bahwa mantan simpatisan radikal di lingkungannya kembali mengumpulkan massa secara tertutup. Sikap Anda sebagai aparat kelurahan?", "opts":[{"t":"Menindaklanjuti laporan dan berkoordinasi dengan kepolisian","s":5},{"t":"Memverifikasi laporan ke lapangan","s":4},{"t":"Mencatat laporan tanpa tindak lanjut","s":3},{"t":"Mengabaikan laporan","s":2},{"t":"Membocorkan identitas pelapor","s":1}], "ex":"Laporan pengumpulan massa tertutup oleh mantan simpatisan harus diverifikasi dan dikoordinasikan dengan polisi."},
{"id":"TKP-4497", "q":"Anda menjadi narasumber seminar dan ditanya tentang mantan narapidana terorisme yang sukses berwirausaha. Sikap Anda?", "opts":[{"t":"Menjadikannya contoh keberhasilan deradikalisasi dan reintegrasi","s":5},{"t":"Mengapresiasi perubahannya","s":4},{"t":"Menjawab normatif tanpa contoh","s":3},{"t":"Menghindar menjawab","s":2},{"t":"Menjelekkannya di forum","s":1}], "ex":"Kisah sukses reintegrasi mantan napiter adalah narasi tanding radikalisme; angkat sebagai contoh."},
{"id":"TKP-4498", "q":"Program beasiswa bagi anak mantan narapidana terorisme diprotes publik sebagai pemborosan. Sikap Anda sebagai pengelola?", "opts":[{"t":"Membela program dengan data pencegahan radikalisasi generasi berikutnya","s":5},{"t":"Tetap menjalankan program sesuai mandat","s":4},{"t":"Mengurangi kuota agar protes reda","s":3},{"t":"Menghentikan program","s":2},{"t":"Mengalihkan dananya","s":1}], "ex":"Beasiswa anak mantan napiter memutus rantai radikalisasi; bela dengan data, jangan hentikan karena protes."},
{"id":"TKP-4499", "q":"Mantan simpatisan ekstrem melamar menjadi pengurus masjid di lingkungan Anda. Jamaah terbelah. Sikap Anda?", "opts":[{"t":"Mendukung dengan masa percobaan dan pembinaan takmir","s":5},{"t":"Memberi kesempatan dengan pengawasan","s":4},{"t":"Netral","s":3},{"t":"Menolak karena masa lalunya","s":2},{"t":"Menggalang penolakan jamaah","s":1}], "ex":"Reintegrasi butuh ruang pembuktian; beri kesempatan berpengurus dengan pembinaan takmir."},
{"id":"TKP-4500", "q":"Anda mengetahui data pribadi mantan narapidana terorisme yang sudah bebas disebar untuk diintimidasi. Sikap Anda?", "opts":[{"t":"Melaporkan penyebaran data itu ke pihak berwajib","s":5},{"t":"Meminta penyebar menghapus data pribadi itu","s":4},{"t":"Mengabaikan","s":3},{"t":"Ikut menyebarkan karena setuju","s":2},{"t":"Menambah informasi pribadinya","s":1}], "ex":"Doxing mantan napiter yang sudah bebas adalah persekusi; laporkan penyebarnya ke berwajib."},
{"id":"TKP-4501", "q":"Rekan kerja memakai istilah thaghut untuk menyebut pemerintah yang sah dalam obrolan kantor yang bernada ekstrem. Sikap Anda?", "opts":[{"t":"Menegur dan melaporkannya sebagai indikasi paparan paham radikal","s":5},{"t":"Menasihatinya agar tidak memakai istilah provokatif","s":4},{"t":"Mengabaikan karena menganggap istilah agama","s":3},{"t":"Ikut memakai istilah itu","s":2},{"t":"Menyebarkan istilah itu ke grup lain","s":1}], "ex":"Istilah thaghut untuk pemerintah sah adalah bahasa kode kelompok ekstrem; tegur dan laporkan sebagai indikasi paparan."},
{"id":"TKP-4502", "q":"Di grup kerja, seseorang memakai kode ikan besar untuk rencana aksi kelompok radikalnya. Anda tidak sengaja membaca. Sikap Anda?", "opts":[{"t":"Melaporkan temuan bahasa kode itu ke pihak berwajib","s":5},{"t":"Menyimpan bukti dan melapor ke atasan","s":4},{"t":"Keluar dari grup tanpa melapor","s":3},{"t":"Mengabaikan karena tidak paham maksudnya","s":2},{"t":"Bertanya cara bergabung","s":1}], "ex":"Bahasa kode rencana aksi kelompok radikal adalah indikasi kejahatan; laporkan ke berwajib dengan bukti."},
{"id":"TKP-4503", "q":"Teman Anda memakai emoji tertentu sebagai kode identifikasi anggota jaringan khilafah di media sosial. Sikap Anda?", "opts":[{"t":"Melaporkan pola kode itu ke pihak berwajib","s":5},{"t":"Menasihatinya berhenti memakai kode jaringan","s":4},{"t":"Mengabaikan","s":3},{"t":"Ikut memakai emoji itu agar terlihat keren","s":2},{"t":"Meminta diajari arti kodenya untuk bergabung","s":1}], "ex":"Emoji sebagai kode identifikasi jaringan khilafah adalah sinyal keanggotaan; laporkan polanya ke berwajib."},
{"id":"TKP-4504", "q":"Seorang penceramah memakai istilah perang suci untuk menghasut jamaah membenci kelompok lain yang intoleran terhadapnya. Anda jamaah. Sikap Anda?", "opts":[{"t":"Melaporkan hasutan berkedok istilah agama itu","s":5},{"t":"Berhenti menghadiri ceramahnya","s":4},{"t":"Menganggapnya retorika biasa","s":3},{"t":"Terpancing emosinya","s":2},{"t":"Ikut menghasut jamaah lain","s":1}], "ex":"Istilah agama yang dipakai menghasut kebencian intoleran adalah manipulasi; tinggalkan dan laporkan penceramahnya."},
{"id":"TKP-4505", "q":"Anak Anda memakai istilah kafir harbi untuk teman sekolahnya yang beda keyakinan setelah bergaul dengan komunitas ekstrem. Sikap Anda?", "opts":[{"t":"Meluruskan pemahamannya, memutus komunitasnya, dan melaporkan","s":5},{"t":"Menasihati keras dan melarang bergaul dengan komunitas itu","s":4},{"t":"Menasihati ringan","s":3},{"t":"Membiarkan karena istilah agama","s":2},{"t":"Mendukungnya","s":1}], "ex":"Istilah kafir harbi untuk teman beda keyakinan adalah doktrin intoleran; luruskan, putus komunitasnya, laporkan."},
{"id":"TKP-4506", "q":"Di forum daring, anggota memakai sandi panen untuk aksi penyerangan terhadap kelompok yang dibenci kaum intoleran. Anda anggota forum. Sikap Anda?", "opts":[{"t":"Segera melaporkan sandi dan rencana itu ke kepolisian","s":5},{"t":"Menyimpan bukti dan melapor","s":4},{"t":"Keluar forum tanpa melapor","s":3},{"t":"Mengabaikan","s":2},{"t":"Ikut merencanakan","s":1}], "ex":"Sandi aksi penyerangan di forum adalah rencana kejahatan; segera laporkan ke polisi dengan bukti."},
{"id":"TKP-4507", "q":"Rekan Anda menyebut aparat sebagai musuh yang halal diperangi dalam diskusi yang mengarah ke paham teror. Sikap Anda?", "opts":[{"t":"Menolak pernyataan itu dan melaporkannya","s":5},{"t":"Mendebatnya bahwa aparat adalah pelindung rakyat","s":4},{"t":"Diam agar tidak ribut","s":3},{"t":"Menganggapnya emosi sesaat","s":2},{"t":"Menyetujuinya","s":1}], "ex":"Penyebutan aparat sebagai musuh yang halal diperangi adalah doktrin teror; tolak dan laporkan."},
{"id":"TKP-4508", "q":"Sebuah lagu yang viral ternyata berisi lirik kode ajakan bergabung jaringan khilafah. Anak Anda menyanyikannya. Sikap Anda?", "opts":[{"t":"Melaporkan lagu itu dan mengedukasi anak tentang maknanya","s":5},{"t":"Melarang anak menyanyikan dan menjelaskan bahayanya","s":4},{"t":"Menganggapnya sekadar lagu","s":3},{"t":"Ikut menyanyikan","s":2},{"t":"Menyebarkan lagu itu","s":1}], "ex":"Lirik kode ajakan jaringan khilafah dalam lagu viral menarget anak muda; laporkan dan edukasi anak."},
{"id":"TKP-4509", "q":"Teman sekantor memakai pin bergambar simbol terselubung kelompok ekstrem dan mengaku hanya aksesori. Sikap Anda?", "opts":[{"t":"Melaporkan ke atasan agar ditertibkan","s":5},{"t":"Menegur dan memintanya melepas","s":4},{"t":"Mengabaikan","s":3},{"t":"Memuji desainnya","s":2},{"t":"Ikut memakai pin serupa","s":1}], "ex":"Simbol terselubung kelompok ekstrem bukan sekadar aksesori; laporkan agar ditertibkan di lingkungan kerja."},
{"id":"TKP-4510", "q":"Dalam rapat, seseorang menyelipkan istilah khilafah sebagai solusi atas semua masalah bangsa dengan nada menghasut. Anda peserta rapat. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan penyusupan agenda itu","s":5},{"t":"Menyanggah bahwa solusinya adalah Pancasila dan konstitusi","s":4},{"t":"Diam","s":3},{"t":"Mengangguk setuju","s":2},{"t":"Mendukung usulannya","s":1}], "ex":"Penyelipan agenda khilafah di forum resmi harus disanggah dan dilaporkan; solusinya Pancasila dan konstitusi."},
{"id":"TKP-4511", "q":"Grup alumni Anda memakai istilah perjuangan untuk penggalangan dana yang ternyata untuk jaringan radikal. Anda anggota grup. Sikap Anda?", "opts":[{"t":"Menolak berdonasi dan melaporkan grup itu","s":5},{"t":"Keluar dari grup dan memperingatkan anggota lain","s":4},{"t":"Keluar diam-diam","s":3},{"t":"Berdonasi kecil","s":2},{"t":"Berdonasi besar","s":1}], "ex":"Istilah perjuangan berkedok donasi untuk jaringan radikal harus ditolak; laporkan grupnya."},
{"id":"TKP-4512", "q":"Anak buah Anda menulis laporan dengan istilah-istilah doktrin intoleran yang merendahkan kelompok lain. Sikap Anda sebagai atasan?", "opts":[{"t":"Menegur, meminta revisi, dan membinanya tentang netralitas ASN","s":5},{"t":"Mengembalikan laporan untuk diperbaiki bahasanya","s":4},{"t":"Membiarkan karena isinya benar","s":3},{"t":"Menyetujui laporannya","s":2},{"t":"Memuji keberaniannya","s":1}], "ex":"Bahasa doktrin intoleran tidak boleh masuk dokumen resmi; tegur, minta revisi, dan bina tentang netralitas."},
{"id":"TKP-4513", "q":"Seorang sopir daring memakai stiker berkode ajakan bergabung kelompok ekstrem di kendaraannya. Anda penumpangnya. Sikap Anda?", "opts":[{"t":"Melaporkan temuan itu ke pihak berwajib setelah turun","s":5},{"t":"Menegur sopir agar melepas stiker","s":4},{"t":"Diam selama perjalanan","s":3},{"t":"Memotret untuk koleksi","s":2},{"t":"Meminta stiker serupa","s":1}], "ex":"Stiker kode ajakan kelompok ekstrem di kendaraan umum adalah propaganda berjalan; laporkan ke berwajib."},
{"id":"TKP-4514", "q":"Di pengajian, ustaz memakai perumpamaan memancing untuk ajakan merekrut anggota jaringan khilafah. Anda jamaah. Sikap Anda?", "opts":[{"t":"Berhenti ikut dan melaporkan modus rekrutmen berkedok perumpamaan itu","s":5},{"t":"Menegur pengurus pengajian","s":4},{"t":"Berhenti hadir diam-diam","s":3},{"t":"Tetap hadir","s":2},{"t":"Ikut direkrut","s":1}], "ex":"Perumpamaan rekrutmen jaringan khilafah di pengajian adalah modus halus; tinggalkan dan laporkan."},
{"id":"TKP-4515", "q":"Teman Anda membuat meme yang mengejek Pancasila dan memuliakan simbol khilafah, lalu viral. Sikap Anda?", "opts":[{"t":"Melaporkan meme itu dan menasihatinya","s":5},{"t":"Memintanya menghapus meme tersebut","s":4},{"t":"Mengabaikan","s":3},{"t":"Tertawa karena lucu","s":2},{"t":"Ikut menyebarkan meme itu","s":1}], "ex":"Meme pengejek Pancasila pemulia khilafah adalah penghinaan ideologi negara; laporkan dan minta dihapus."},
{"id":"TKP-4516", "q":"Seorang pedagang memakai slogan dagang yang ternyata kode dukungan pada aksi teror kelompok tertentu. Anda pelanggannya. Sikap Anda?", "opts":[{"t":"Tidak berbelanja di sana dan melaporkannya","s":5},{"t":"Menegur pedagang agar mengganti slogan","s":4},{"t":"Tetap berbelanja tanpa peduli","s":3},{"t":"Memuji slogannya yang unik","s":2},{"t":"Membantu mempromosikan dagangannya","s":1}], "ex":"Slogan kode dukungan aksi teror adalah propaganda terselubung; jangan berbelanja di sana dan laporkan."},
{"id":"TKP-4517", "q":"Dalam diskusi keluarga, keponakan remaja Anda memakai argumen bahwa bom bunuh diri adalah mati syahid menurut paham ekstremnya. Sikap Anda?", "opts":[{"t":"Meluruskan dengan tegas dan melaporkan indikasi paparannya","s":5},{"t":"Mendebatnya bahwa itu pembunuhan, bukan syahid","s":4},{"t":"Mengalihkan topik pembicaraan","s":3},{"t":"Membiarkan karena masih remaja","s":2},{"t":"Membenarkan argumennya","s":1}], "ex":"Argumen bom bunuh diri sebagai syahid adalah doktrin teror; luruskan tegas dan laporkan paparannya."},
{"id":"TKP-4518", "q":"Sebuah komunitas hobi memakai nama samaran yang merujuk pada tokoh terorisme internasional. Anda anggotanya. Sikap Anda?", "opts":[{"t":"Memprotes dan melaporkan ke pengurus serta berwajib bila terafiliasi","s":5},{"t":"Mengusulkan penggantian nama komunitas","s":4},{"t":"Keluar diam-diam","s":3},{"t":"Tetap bergabung karena hobinya seru","s":2},{"t":"Mendukung nama itu","s":1}], "ex":"Nama samaran merujuk tokoh terorisme adalah glorifikasi; protes dan laporkan bila terafiliasi jaringan."},
{"id":"TKP-4519", "q":"Atasan Anda memakai istilah pembersihan untuk rencana mutasi pegawai yang beda keyakinan dengannya yang intoleran. Sikap Anda?", "opts":[{"t":"Menolak istilah diskriminatif dan melaporkan ke pimpinan lebih tinggi","s":5},{"t":"Menasihati atasan agar tidak diskriminatif","s":4},{"t":"Diam","s":3},{"t":"Mendukung rencananya","s":2},{"t":"Membantu menyusun daftar mutasi","s":1}], "ex":"Istilah pembersihan untuk mutasi diskriminatif adalah intoleransi struktural; tolak dan laporkan ke pimpinan."},
{"id":"TKP-4520", "q":"Anda menemukan buku catatan berisi daftar kode dan jadwal pertemuan tertutup jaringan khilafah milik teman kos. Sikap Anda?", "opts":[{"t":"Segera melaporkan temuan itu ke pihak kepolisian","s":5},{"t":"Memotret sebagai bukti lalu melapor","s":4},{"t":"Mengembalikannya tanpa melapor","s":3},{"t":"Membacanya diam-diam","s":2},{"t":"Ikut menghadiri pertemuannya","s":1}], "ex":"Daftar kode dan jadwal pertemuan jaringan khilafah adalah bukti penting; segera laporkan ke polisi."},
{"id":"TKP-4521", "q":"Seorang penceramah daring memakai kode hijrah total untuk ajakan keluar dari NKRI dan bergabung khilafah. Anda penontonnya. Sikap Anda?", "opts":[{"t":"Melaporkan kanal itu dan berhenti menonton","s":5},{"t":"Berhenti menonton dan memberi peringatan","s":4},{"t":"Mengabaikan","s":3},{"t":"Tertarik dengan ajakannya","s":2},{"t":"Menghubungi penceramah untuk bergabung","s":1}], "ex":"Kode hijrah total untuk keluar dari NKRI adalah ajakan makar berkedok dakwah; laporkan kanalnya."},
{"id":"TKP-4522", "q":"Teman Anda mengirim pesan terenkripsi berisi jadwal latihan perang kelompok ekstrem dan meminta Anda menghapus setelah dibaca. Sikap Anda?", "opts":[{"t":"Melaporkan pesan itu ke pihak berwajib","s":5},{"t":"Menyimpan bukti dan melapor","s":4},{"t":"Menghapus seperti diminta","s":3},{"t":"Membaca lalu mengabaikan","s":2},{"t":"Ikut latihan perangnya","s":1}], "ex":"Pesan jadwal latihan perang kelompok ekstrem adalah indikasi terorisme; laporkan ke berwajib, jangan hapus bukti."},
{"id":"TKP-4523", "q":"Di tempat ibadah, pengurus baru mengganti bacaan doa dengan selipan kutukan intoleran terhadap kelompok lain. Anda jamaah. Sikap Anda?", "opts":[{"t":"Melaporkan ke pengurus lama dan tokoh agama setempat","s":5},{"t":"Memprotes penggantian doa itu","s":4},{"t":"Pindah tempat ibadah","s":3},{"t":"Mengikuti saja","s":2},{"t":"Mendukung doa barunya","s":1}], "ex":"Doa yang disisipi kutukan intoleran menodai ibadah; protes dan laporkan ke pengurus dan tokoh agama."},
{"id":"TKP-4524", "q":"Sebuah kaos yang dijual daring bergambar peta dengan tanda silang pada Pancasila dan tulisan khilafah. Teman Anda memakainya. Sikap Anda?", "opts":[{"t":"Menasihatinya melepas dan melaporkan penjualnya","s":5},{"t":"Menegur teman agar tidak memakai","s":4},{"t":"Mengabaikan","s":3},{"t":"Memuji desainnya","s":2},{"t":"Ikut membeli","s":1}], "ex":"Kaos penghina Pancasila pemuja khilafah adalah propaganda wearable; tegur pemakai dan laporkan penjualnya."},
{"id":"TKP-4525", "q":"Anda mendengar dua orang memakai bahasa isyarat tangan khusus kelompok ekstrem saat bertemu di mal. Sikap Anda?", "opts":[{"t":"Mencatat ciri-cirinya dan melaporkan ke pihak keamanan","s":5},{"t":"Melaporkan ke petugas keamanan mal","s":4},{"t":"Mengabaikan","s":3},{"t":"Mengikuti mereka untuk memastikan","s":2},{"t":"Mendekati dan menyapa","s":1}], "ex":"Isyarat khusus kelompok ekstrem di ruang publik patut diwaspadai; catat ciri dan laporkan ke keamanan, jangan dekati sendiri."},
{"id":"TKP-4526", "q":"Anda menyaksikan tetangga menyimpan senjata rakitan dan bendera kelompok ekstrem di rumahnya. Tindakan pertama Anda?", "opts":[{"t":"Segera melaporkan ke kepolisian setempat","s":5},{"t":"Melaporkan ke ketua RT dan polisi","s":4},{"t":"Menceritakan ke tetangga lain","s":3},{"t":"Mengabaikan karena takut","s":2},{"t":"Ikut menyimpannya","s":1}], "ex":"Temuan senjata dan simbol kelompok ekstrem adalah keadaan darurat keamanan; segera laporkan ke polisi."},
{"id":"TKP-4527", "q":"Rekan kerja Anda menjadi korban intimidasi kelompok intoleran karena menolak bergabung. Ia meminta saran Anda. Sikap Anda?", "opts":[{"t":"Mendampinginya melapor ke polisi dan pimpinan","s":5},{"t":"Menasihatinya melapor dan memberi dukungan","s":4},{"t":"Menyarankan pindah kerja","s":3},{"t":"Menyarankan mengalah saja","s":2},{"t":"Menyarankan bergabung agar aman","s":1}], "ex":"Korban intimidasi kelompok intoleran wajib didampingi melapor ke polisi; jangan sarankan mengalah."},
{"id":"TKP-4528", "q":"Anda menerima ancaman pembunuhan dari nomor tak dikenal karena melaporkan aktivitas kelompok radikal. Sikap Anda?", "opts":[{"t":"Melaporkan ancaman itu ke polisi dan meminta perlindungan","s":5},{"t":"Menyimpan bukti ancaman dan melapor","s":4},{"t":"Mengabaikan ancaman","s":3},{"t":"Menarik laporan Anda","s":2},{"t":"Meminta maaf ke kelompok itu","s":1}], "ex":"Ancaman terhadap pelapor kelompok radikal harus dilaporkan ke polisi; minta perlindungan, jangan tarik laporan."},
{"id":"TKP-4529", "q":"Sebagai admin grup warga, Anda menemukan anggota menyebarkan rekrutmen jaringan teror. Tindakan Anda?", "opts":[{"t":"Mengeluarkan anggota, menghapus konten, dan melaporkannya","s":5},{"t":"Menghapus konten dan memperingatkan","s":4},{"t":"Membiarkan karena takut","s":3},{"t":"Mengabaikan","s":2},{"t":"Ikut menyebarkan","s":1}], "ex":"Rekrutmen jaringan teror di grup warga harus ditindak: keluarkan, hapus, dan laporkan pelakunya."},
{"id":"TKP-4530", "q":"Anak Anda menjadi saksi perundungan bernada intoleran ekstrem di sekolah dan takut melapor. Sikap Anda?", "opts":[{"t":"Mendampingi anak melapor ke guru dan kepala sekolah","s":5},{"t":"Melaporkan kejadian ke pihak sekolah","s":4},{"t":"Menasihati anak menghindar","s":3},{"t":"Membiarkan karena takut anak diincar","s":2},{"t":"Menyuruh anak membalas","s":1}], "ex":"Saksi perundungan intoleran harus didampingi melapor ke sekolah; jangan biarkan takut membungkam kebenaran."},
{"id":"TKP-4531", "q":"Anda mengetahui identitas whistleblower kasus jaringan radikal di kantor Anda dibocorkan oknum. Sikap Anda?", "opts":[{"t":"Melaporkan pembocoran itu ke pimpinan dan pihak berwajib","s":5},{"t":"Melindungi whistleblower dan melaporkan oknum","s":4},{"t":"Diam","s":3},{"t":"Ikut menyebarkan identitasnya","s":2},{"t":"Mengintimidasi whistleblower","s":1}], "ex":"Identitas pelapor jaringan radikal wajib dilindungi; pembocornya harus dilaporkan ke pimpinan dan berwajib."},
{"id":"TKP-4532", "q":"Hotline pelaporan konten ekstrem yang Anda hubungi tidak merespons laporan Anda tentang kanal khilafah. Sikap Anda?", "opts":[{"t":"Melapor ulang lewat kanal resmi lain seperti polisi dan Kominfo","s":5},{"t":"Mencoba kanal pelaporan alternatif","s":4},{"t":"Menyerah","s":3},{"t":"Menyebarkan sendiri ke media sosial","s":2},{"t":"Membiarkan kanal itu","s":1}], "ex":"Laporan tak direspons bukan alasan berhenti; gunakan kanal resmi lain seperti polisi dan Kominfo."},
{"id":"TKP-4533", "q":"Teman Anda takut melapor ke polisi tentang perekrutan kelompok ekstrem karena khawatir identitasnya terbongkar. Saran Anda?", "opts":[{"t":"Menjelaskan perlindungan pelapor dan mendampinginya melapor","s":5},{"t":"Meyakinkannya bahwa identitas pelapor dilindungi undang-undang","s":4},{"t":"Menyarankan lapor anonim lewat hotline","s":3},{"t":"Menyarankan tidak usah melapor","s":2},{"t":"Ikut menakutinya agar diam","s":1}], "ex":"Ketakutan melapor harus diatasi dengan penjelasan perlindungan pelapor dan pendampingan, bukan dibiarkan."},
{"id":"TKP-4534", "q":"Anda melihat spanduk perekrutan kelompok khilafah terpasang di jalan protokol. Tindakan Anda?", "opts":[{"t":"Melaporkan ke polisi dan satpol PP agar diturunkan","s":5},{"t":"Memotret sebagai bukti lalu melapor","s":4},{"t":"Mengabaikan","s":3},{"t":"Membaca isinya dengan saksama","s":2},{"t":"Menghubungi nomor di spanduk","s":1}], "ex":"Spanduk perekrutan khilafah di ruang publik harus dilaporkan ke polisi dan Satpol PP agar diturunkan."},
{"id":"TKP-4535", "q":"Sebagai guru BK, siswa Anda mengaku direkrut jaringan ekstrem dan ingin keluar tetapi takut. Sikap Anda?", "opts":[{"t":"Melaporkan ke kepala sekolah dan polisi serta mendampingi siswa","s":5},{"t":"Menampung pengakuannya dan menghubungi orang tuanya","s":4},{"t":"Menasihati agar menjauh","s":3},{"t":"Merahasiakan tanpa melapor","s":2},{"t":"Mengabaikan pengakuannya","s":1}], "ex":"Siswa korban rekrutmen yang ingin keluar harus dilindungi; laporkan ke sekolah dan polisi serta dampingi."},
{"id":"TKP-4536", "q":"Anda menemukan USB berisi daftar anggota dan rencana aksi kelompok teror yang tertinggal di warnet. Tindakan Anda?", "opts":[{"t":"Segera menyerahkan USB itu ke kepolisian","s":5},{"t":"Membawa ke kantor polisi terdekat","s":4},{"t":"Menyimpan tanpa melapor","s":3},{"t":"Membuka isinya untuk dibaca","s":2},{"t":"Mengembalikannya ke pemiliknya","s":1}], "ex":"Temuan daftar anggota dan rencana aksi kelompok teror adalah bukti krusial; segera serahkan ke polisi."},
{"id":"TKP-4537", "q":"Ketua komunitas Anda melarang anggota melapor ke polisi tentang aktivitas radikal di komunitasnya. Sikap Anda?", "opts":[{"t":"Tetap melapor ke polisi karena itu kewajiban warga","s":5},{"t":"Melapor diam-diam ke pihak berwajib","s":4},{"t":"Mematuhi larangan ketua","s":3},{"t":"Keluar komunitas tanpa melapor","s":2},{"t":"Ikut menutupi aktivitas itu","s":1}], "ex":"Larangan melapor dari ketua komunitas tidak berlaku untuk kejahatan; kewajiban warga adalah melapor ke polisi."},
{"id":"TKP-4538", "q":"Anda menyaksikan transaksi mencurigakan yang diduga pendanaan jaringan ekstrem di bank tempat Anda bekerja. Sikap Anda?", "opts":[{"t":"Melaporkan ke atasan dan PPATK sesuai prosedur","s":5},{"t":"Melaporkan ke bagian kepatuhan bank","s":4},{"t":"Mencatat tanpa melapor","s":3},{"t":"Mengabaikan","s":2},{"t":"Membantu memuluskan transaksi","s":1}], "ex":"Transaksi diduga pendanaan ekstrem wajib dilaporkan ke kepatuhan bank dan PPATK sesuai prosedur."},
{"id":"TKP-4539", "q":"Tetangga Anda mengancam akan melaporkan Anda sebagai simpatisan teror jika Anda melapor ke polisi. Sikap Anda?", "opts":[{"t":"Tetap melapor dan melaporkan balik ancamannya","s":5},{"t":"Melapor dengan pengamanan identitas","s":4},{"t":"Membatalkan niat melapor","s":3},{"t":"Meminta maaf ke tetangga","s":2},{"t":"Tunduk dan diam selamanya","s":1}], "ex":"Ancaman balik dari tetangga tidak boleh menghentikan laporan; laporkan ancaman itu juga ke polisi."},
{"id":"TKP-4540", "q":"Sebagai petugas call center, Anda menerima laporan warga tentang ceramah ekstrem di lingkungannya. Sikap Anda?", "opts":[{"t":"Mencatat detail dan meneruskan ke unit penanganan","s":5},{"t":"Menindaklanjuti laporan sesuai SOP","s":4},{"t":"Mencatat tanpa meneruskan","s":3},{"t":"Mengabaikan laporan","s":2},{"t":"Mengejek pelapor","s":1}], "ex":"Laporan warga tentang ceramah ekstrem wajib dicatat dan diteruskan ke unit penanganan sesuai SOP."},
{"id":"TKP-4541", "q":"Anda diminta menjadi saksi dalam persidangan kasus terorisme. Keluarga Anda khawatir. Sikap Anda?", "opts":[{"t":"Bersedia bersaksi dengan meminta perlindungan saksi","s":5},{"t":"Bersedia bersaksi demi keadilan","s":4},{"t":"Menolak karena takut","s":3},{"t":"Memberi kesaksian palsu","s":2},{"t":"Melarikan diri","s":1}], "ex":"Kesaksian dalam kasus terorisme adalah kewajiban warga; minta perlindungan saksi dari LPSK bila khawatir."},
{"id":"TKP-4542", "q":"Media sosial Anda dibanjiri pesan ancaman setelah Anda melaporkan akun propaganda khilafah. Sikap Anda?", "opts":[{"t":"Melaporkan ancaman itu ke polisi dan platform","s":5},{"t":"Memblokir pengancam dan menyimpan bukti","s":4},{"t":"Menghapus laporan Anda","s":3},{"t":"Menonaktifkan akun karena takut","s":2},{"t":"Meminta maaf ke pemilik akun","s":1}], "ex":"Teror balik atas pelaporan propaganda khilafah harus dilaporkan ke polisi; jangan tarik laporan karena takut."},
{"id":"TKP-4543", "q":"Anda menemukan peta dan jadwal patroli aparat di ponsel teman yang terindikasi anggota jaringan ekstrem. Sikap Anda?", "opts":[{"t":"Segera melaporkan temuan itu ke pihak berwajib","s":5},{"t":"Memotret bukti dan melapor","s":4},{"t":"Menghapus temuan dari ingatan","s":3},{"t":"Mengabaikan","s":2},{"t":"Ikut menyebarkan peta itu","s":1}], "ex":"Peta dan jadwal patroli di tangan jaringan ekstrem membahayakan aparat; segera laporkan ke berwajib."},
{"id":"TKP-4544", "q":"Sebagai pengurus RT, warga melapor ada kontrakan yang menjadi tempat kumpul tertutup kelompok intoleran. Sikap Anda?", "opts":[{"t":"Memverifikasi dan melaporkan ke polisi serta pemilik kontrakan","s":5},{"t":"Mendatangi kontrakan bersama warga dan aparat","s":4},{"t":"Mencatat laporan tanpa tindak lanjut","s":3},{"t":"Mengabaikan","s":2},{"t":"Melarang warga melapor","s":1}], "ex":"Laporan tempat kumpul tertutup kelompok intoleran harus diverifikasi dan diteruskan ke polisi."},
{"id":"TKP-4545", "q":"Anda menerima email ancaman bom di kantor dari kelompok yang menamakan diri pejuang khilafah. Tindakan pertama Anda?", "opts":[{"t":"Segera melaporkan ke keamanan dan kepolisian serta mengikuti SOP evakuasi","s":5},{"t":"Meneruskan email ke atasan dan keamanan","s":4},{"t":"Menghapus email","s":3},{"t":"Mengabaikan karena menganggap iseng","s":2},{"t":"Menyebarkan ke grup kantor hingga panik","s":1}], "ex":"Ancaman bom wajib dilaporkan ke keamanan dan polisi serta ikuti SOP evakuasi; jangan sebarkan hingga panik."},
{"id":"TKP-4546", "q":"Teman sekantor Anda dilecehkan kelompok intoleran karena membela minoritas. Ia ingin mengundurkan diri. Saran Anda?", "opts":[{"t":"Mendukungnya bertahan, melapor, dan memberi dukungan moral","s":5},{"t":"Menasihatinya melapor ke polisi dan pimpinan","s":4},{"t":"Menyarankan cuti menenangkan diri","s":3},{"t":"Menyarankan mengundurkan diri","s":2},{"t":"Menyarankan minta maaf ke kelompok itu","s":1}], "ex":"Korban pelecehan intoleran harus didukung bertahan dan melapor; jangan biarkan intimidasi menang."},
{"id":"TKP-4547", "q":"Anda mengetahui jadwal dan rute konvoi massa intoleran yang akan menyerang acara keagamaan kelompok lain. Sikap Anda?", "opts":[{"t":"Segera melaporkan informasi itu ke kepolisian","s":5},{"t":"Memberitahu panitia acara dan aparat","s":4},{"t":"Menyimpan informasi sendiri","s":3},{"t":"Mengabaikan","s":2},{"t":"Ikut dalam konvoi","s":1}], "ex":"Informasi rencana penyerangan acara keagamaan harus segera sampai ke polisi untuk pencegahan."},
{"id":"TKP-4548", "q":"Sebagai satpam mal, Anda menemukan tas mencurigakan dan selebaran propaganda teror di area parkir. Tindakan Anda?", "opts":[{"t":"Mengamankan area, melapor ke atasan, dan menghubungi polisi","s":5},{"t":"Melaporkan temuan ke pusat komando keamanan","s":4},{"t":"Membuang selebaran dan mengabaikan tas","s":3},{"t":"Membuka tas untuk memeriksa","s":2},{"t":"Menyembunyikan temuan","s":1}], "ex":"Temuan tas mencurigakan plus propaganda teror wajib diamankan areanya dan dilaporkan ke polisi; jangan dibuka sendiri."},
{"id":"TKP-4549", "q":"Anda diminta menandatangani petisi dukungan moril bagi pelaku teror yang diadili. Sikap Anda?", "opts":[{"t":"Menolak dan melaporkan penggalang petisi","s":5},{"t":"Menolak dengan tegas","s":4},{"t":"Menolak dengan halus","s":3},{"t":"Menandatangani karena sungkan","s":2},{"t":"Menandatangani dan mengajak lain","s":1}], "ex":"Petisi dukungan bagi pelaku teror adalah pembelaan terhadap kejahatan; tolak dan laporkan penggalangnya."},
{"id":"TKP-4550", "q":"Lingkungan Anda akan mengadakan ronda gabungan untuk mewaspadai penyebaran paham radikal. Sikap Anda?", "opts":[{"t":"Ikut aktif ronda dan berkoordinasi dengan aparat serta melaporkan temuan","s":5},{"t":"Ikut ronda sesuai jadwal","s":4},{"t":"Mendukung tanpa ikut","s":3},{"t":"Menolak ikut karena repot","s":2},{"t":"Menentang ronda dan membela kelompok radikal","s":1}], "ex":"Ronda gabungan cegah radikalisme adalah siskamling modern; ikut aktif dan koordinasikan temuan dengan aparat."}
];
